import * as THREE from 'three';
import { FIELD, clamp } from './constants.js';

function makeBallTexture() {
  const size = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size / 2;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#e8edf7';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Soft blue shading bands.
  const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, 'rgba(110,150,210,0.32)');
  grad.addColorStop(0.45, 'rgba(255,255,255,0)');
  grad.addColorStop(1, 'rgba(70,100,160,0.28)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Hex grid.
  const r = 44;
  const h = Math.sin(Math.PI / 3) * r;
  ctx.strokeStyle = 'rgba(20,34,62,0.55)';
  ctx.lineWidth = 7;
  ctx.lineJoin = 'round';
  for (let row = -1; row < canvas.height / h + 2; row += 1) {
    for (let col = -1; col < canvas.width / (r * 1.5) + 2; col += 1) {
      const cx = col * r * 1.5;
      const cy = row * h * 2 + (col % 2 ? h : 0);
      ctx.beginPath();
      for (let i = 0; i < 6; i += 1) {
        const a = (Math.PI / 3) * i;
        const x = cx + Math.cos(a) * r;
        const y = cy + Math.sin(a) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.stroke();
    }
  }

  // Small team-coloured flecks to catch the light.
  for (let i = 0; i < 90; i += 1) {
    ctx.fillStyle = Math.random() < 0.5 ? 'rgba(60,150,255,0.12)' : 'rgba(255,120,40,0.10)';
    ctx.beginPath();
    ctx.arc(Math.random() * canvas.width, Math.random() * canvas.height, Math.random() * 20 + 4, 0, Math.PI * 2);
    ctx.fill();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function makeGlowTexture() {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 256;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
  g.addColorStop(0, 'rgba(255,255,255,0.9)');
  g.addColorStop(0.2, 'rgba(180,225,255,0.5)');
  g.addColorStop(0.5, 'rgba(90,170,255,0.16)');
  g.addColorStop(1, 'rgba(20,60,140,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export class Ball {
  constructor(scene) {
    this.scene = scene;
    this.radius = FIELD.ballRadius;
    this.pos = new THREE.Vector3(0, this.radius + 0.2, 0);
    this.vel = new THREE.Vector3();
    this.spin = new THREE.Vector3();
    this.onEvent = () => {};
    this.trailTimer = 0;
    this.lastTouch = 'blue';
    this.hitFlash = 0;

    this.group = new THREE.Group();
    const geo = new THREE.SphereGeometry(this.radius, 48, 32);
    const mat = new THREE.MeshPhysicalMaterial({
      map: makeBallTexture(),
      color: 0xffffff,
      metalness: 0.28,
      roughness: 0.32,
      clearcoat: 0.75,
      clearcoatRoughness: 0.2,
      emissive: 0x1a2c4a,
      emissiveIntensity: 0.5,
    });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = false;
    this.group.add(this.mesh);

    // Faint crystalline cage to make the ball read at distance.
    const cage = new THREE.Mesh(
      new THREE.IcosahedronGeometry(this.radius * 1.008, 2),
      new THREE.MeshBasicMaterial({
        color: 0x9fd8ff,
        wireframe: true,
        transparent: true,
        opacity: 0.075,
        depthWrite: false,
      }),
    );
    this.group.add(cage);

    const glowMat = new THREE.SpriteMaterial({
      map: makeGlowTexture(),
      color: 0x9ed8ff,
      transparent: true,
      opacity: 0.52,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: true,
    });
    this.glow = new THREE.Sprite(glowMat);
    this.glow.scale.setScalar(11);
    this.group.add(this.glow);

    this.light = new THREE.PointLight(0x9fd8ff, 8, 20, 2);
    this.light.position.set(0, 0, 0);
    this.group.add(this.light);

    scene.add(this.group);
    this.group.position.copy(this.pos);
  }

  reset(x = 0, z = 0) {
    this.pos.set(x, this.radius + 0.15, z);
    this.vel.set(0, 0, 0);
    this.spin.set(0, 0, 0);
    this.group.position.copy(this.pos);
    this.mesh.quaternion.identity();
    this.hitFlash = 0;
    this.light.intensity = 8;
  }

  update(dt, fx = null, active = true) {
    if (!active) {
      this.mesh.rotation.y += dt * 0.18;
      this.light.intensity = 6 + Math.sin(performance.now() * 0.002) * 1.4;
      return;
    }

    const speed = this.vel.length();
    this.vel.y -= FIELD.gravity * dt;
    this.pos.addScaledVector(this.vel, dt);

    // Floor.
    if (this.pos.y < this.radius) {
      const impact = -this.vel.y;
      this.pos.y = this.radius;
      if (this.vel.y < -1.2) {
        this.vel.y = -this.vel.y * 0.66;
        this.vel.x *= 0.985;
        this.vel.z *= 0.985;
        if (impact > 6) {
          this.onEvent('bounce', impact);
          if (fx) {
            fx.emit(this.pos, {
              count: Math.round(impact * 0.7),
              color: 0xbfe6ff,
              speed: 4,
              spread: 4,
              life: 0.35,
              size: 0.25,
              gravity: 8,
              jitter: 0.8,
            });
          }
        }
      } else {
        this.vel.y = 0;
        const roll = Math.exp(-0.72 * dt);
        this.vel.x *= roll;
        this.vel.z *= roll;
      }
    }

    // Side glass.
    const side = FIELD.halfWidth - this.radius;
    if (this.pos.z > side) {
      this.pos.z = side;
      if (this.vel.z > 0) {
        this.vel.z = -this.vel.z * 0.72;
        this.onEvent('wall', Math.abs(this.vel.z));
      }
    } else if (this.pos.z < -side) {
      this.pos.z = -side;
      if (this.vel.z < 0) {
        this.vel.z = -this.vel.z * 0.72;
        this.onEvent('wall', Math.abs(this.vel.z));
      }
    }

    // Ceiling.
    const top = FIELD.ceiling - this.radius;
    if (this.pos.y > top) {
      this.pos.y = top;
      this.vel.y = -Math.abs(this.vel.y) * 0.6;
    }

    // Ends, with goal mouths cut out.
    const inMouth = Math.abs(this.pos.z) < FIELD.goalHalfWidth - 0.4 && this.pos.y < FIELD.goalHeight - 0.25;
    const end = FIELD.halfLength - this.radius;
    if (!inMouth) {
      if (this.pos.x > end) {
        this.pos.x = end;
        if (this.vel.x > 0) {
          this.vel.x = -this.vel.x * 0.72;
          this.onEvent('wall', Math.abs(this.vel.x));
        }
      } else if (this.pos.x < -end) {
        this.pos.x = -end;
        if (this.vel.x < 0) {
          this.vel.x = -this.vel.x * 0.72;
          this.onEvent('wall', Math.abs(this.vel.x));
        }
      }
    } else {
      const back = FIELD.halfLength + FIELD.goalDepth - this.radius;
      if (this.pos.x > back) {
        this.pos.x = back;
        this.vel.x = -Math.abs(this.vel.x) * 0.35;
      } else if (this.pos.x < -back) {
        this.pos.x = -back;
        this.vel.x = Math.abs(this.vel.x) * 0.35;
      }
      // Net side walls.
      const netSide = FIELD.goalHalfWidth - this.radius * 0.4;
      if (Math.abs(this.pos.x) > FIELD.halfLength - this.radius) {
        if (this.pos.z > netSide) {
          this.pos.z = netSide;
          this.vel.z = -Math.abs(this.vel.z) * 0.4;
        } else if (this.pos.z < -netSide) {
          this.pos.z = -netSide;
          this.vel.z = Math.abs(this.vel.z) * 0.4;
        }
      }
    }

    if (this.pos.y > FIELD.ceiling + 4 || Math.abs(this.pos.x) > FIELD.halfLength + FIELD.goalDepth + 6) {
      this.reset(0, 0);
      this.onEvent('reset');
    }

    // Rolling spin.
    const horiz = Math.hypot(this.vel.x, this.vel.z);
    if (horiz > 0.05) {
      const axis = new THREE.Vector3(-this.vel.z, 0, this.vel.x).normalize();
      const angle = (horiz * dt) / this.radius;
      const q = new THREE.Quaternion().setFromAxisAngle(axis, angle);
      this.mesh.quaternion.premultiply(q);
    } else {
      this.mesh.rotation.y += dt * 0.15;
    }

    // Speed-based glow and trail.
    const t = clamp(speed / 48, 0, 1);
    this.light.intensity = 7 + t * 26;
    this.light.color.setHSL(0.56 - t * 0.05, 0.75, 0.62 + t * 0.15);
    this.glow.material.opacity = 0.42 + t * 0.4;
    this.glow.scale.setScalar(10 + t * 8);
    this.group.position.copy(this.pos);

    if (fx && speed > 9) {
      this.trailTimer -= dt;
      if (this.trailTimer <= 0) {
        this.trailTimer = 0.035;
        fx.trail(this.pos, speed > 38 ? 0xfff0b0 : 0xa8e0ff, 0.5 + t * 0.3, 0.55, 0.5);
      }
    }

    this.hitFlash = Math.max(0, this.hitFlash - dt);
  }
}

import * as THREE from 'three';
import { BOT_LEVELS, FIELD, clamp, rand, wrapAngle } from './constants.js';

export class Bot {
  constructor(level = 'pro') {
    this.setLevel(level);
    this.target = new THREE.Vector3();
    this.tmp = new THREE.Vector3();
    this.thinkTimer = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.jumpCooldown = 0;
    this.boostTimer = 0;
  }

  setLevel(level) {
    this.level = level;
    this.skill = BOT_LEVELS[level] ?? BOT_LEVELS.pro;
  }

  reset() {
    this.thinkTimer = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.jumpCooldown = 0;
    this.boostTimer = 0;
  }

  chooseTarget(game, car) {
    const ball = game.ball;
    const skill = this.skill;
    const lead = 0.16 + (1 - skill.reaction) * 0.12;
    const predicted = this.tmp.copy(ball.pos).addScaledVector(ball.vel, lead);
    predicted.y = 0;

    const attackGoal = new THREE.Vector3(-FIELD.halfLength + 4, 0, 0);
    const dirToGoal = attackGoal.clone().sub(predicted);
    dirToGoal.y = 0;
    if (dirToGoal.lengthSq() < 0.001) dirToGoal.set(-1, 0, 0);
    dirToGoal.normalize();

    // Stand on the far side of the ball from the goal we are attacking.
    const target = predicted.clone().addScaledVector(dirToGoal, -5.2);

    // If we are caught on the wrong side of the ball, swing wide instead of
    // driving through it toward our own net.
    const wrongSide = (car.pos.x - predicted.x) * -dirToGoal.x < 0;
    if (wrongSide && Math.abs(car.pos.x - predicted.x) < 9) {
      const side = ball.pos.z >= 0 ? -1 : 1;
      const swing = Math.sign(car.pos.z - ball.pos.z) || side;
      target.z += swing * (8 + skill.aimNoise * 2);
      target.x += 2;
    }

    // If the ball is above us, shadow its landing spot rather than parking under it.
    if (ball.pos.y > 5.5 && ball.vel.y < 0) {
      const t = clamp(ball.pos.y / 14, 0, 1);
      target.x = ball.pos.x + ball.vel.x * t * 0.55;
      target.z = ball.pos.z + ball.vel.z * t * 0.55;
    }

    // Never chase a ball that is sitting inside our own goal mouth.
    if (target.x > FIELD.halfLength - 7) target.x = FIELD.halfLength - 7;
    if (target.x < -FIELD.halfLength + 5) target.x = -FIELD.halfLength + 5;
    target.z = clamp(target.z, -FIELD.halfWidth + 4, FIELD.halfWidth - 4);

    target.x += rand(-skill.aimNoise, skill.aimNoise);
    target.z += rand(-skill.aimNoise, skill.aimNoise);
    this.target.copy(target);
  }

  update(dt, game) {
    const car = game.botCar;
    const ball = game.ball;
    this.thinkTimer -= dt;
    this.jumpCooldown -= dt;
    this.boostTimer -= dt;

    if (this.thinkTimer <= 0) {
      this.thinkTimer = this.skill.reaction * rand(0.75, 1.3);
      this.chooseTarget(game, car);
    }

    const toTarget = this.tmp.copy(this.target).sub(car.pos);
    toTarget.y = 0;
    const distance = toTarget.length();
    const desiredYaw = Math.atan2(-toTarget.z, toTarget.x);
    const diff = wrapAngle(desiredYaw - car.yaw);
    const facing = Math.cos(diff);

    let steer = clamp(diff * 2.4 + clamp(car.vel.dot(car.right) * -0.035, -0.25, 0.25), -1, 1);
    let throttle = 1;

    if (Math.abs(diff) > 2.35) {
      // Tight turnaround: reverse while steering out of the corner.
      throttle = -0.8;
      steer = clamp(-steer, -1, 1);
    } else if (Math.abs(diff) > 1.15) {
      throttle = 0.55;
    }

    // Stuck recovery near a wall.
    if (car.speed < 2.2 && Math.abs(throttle) > 0.4 && this.reverseTimer <= 0) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 0.9) {
        this.reverseTimer = 0.65;
        this.stuckTimer = 0;
      }
    } else if (this.reverseTimer <= 0) {
      this.stuckTimer = Math.max(0, this.stuckTimer - dt * 2);
    }
    if (this.reverseTimer > 0) {
      this.reverseTimer -= dt;
      throttle = -1;
      steer = clamp(-steer, -1, 1);
    }

    const ballDistance = car.pos.distanceTo(ball.pos);
    const aligned = facing > 0.72;
    let boost = false;
    if (car.boost > 8 && this.boostTimer <= 0 && distance > 9 && aligned) {
      boost = Math.random() < this.skill.boostLove * 0.9 + 0.05;
      if (boost) this.boostTimer = 0.1;
    }
    if (ballDistance < 10 && ballDistance > 3 && aligned && car.boost > 5) {
      boost = Math.random() < this.skill.boostLove * 0.55;
    }
    if (this.reverseTimer > 0) boost = false;

    let jump = false;
    if (this.jumpCooldown <= 0) {
      const ballAbove = ball.pos.y - car.pos.y;
      const close = ballDistance < 8.2;
      if (car.grounded && close && ballAbove > 2.2 && ballAbove < 5.5 && Math.random() < this.skill.jumpLove) {
        jump = true;
        this.jumpCooldown = 0.55;
      } else if (!car.grounded && car.jumps === 1 && close && ballAbove > 1.5 && ballAbove < 4.5) {
        if (Math.random() < this.skill.jumpLove * 0.7) {
          jump = true;
          this.jumpCooldown = 0.7;
        }
      }
    }

    // Ball rolling toward our net: prioritize getting goal-side quickly.
    if (ball.pos.x > 25 && ball.vel.x > 5 && car.pos.x < ball.pos.x) {
      boost = car.boost > 10;
      throttle = 1;
      if (facing < 0.1) steer = clamp(steer + Math.sign(ball.pos.z - car.pos.z) * 0.5, -1, 1);
    }

    return { throttle, steer, boost, jump };
  }
}

const FORWARD_KEYS = new Set(['KeyW', 'ArrowUp']);
const BACK_KEYS = new Set(['KeyS', 'ArrowDown']);
const LEFT_KEYS = new Set(['KeyA', 'ArrowLeft']);
const RIGHT_KEYS = new Set(['KeyD', 'ArrowRight']);
const BOOST_KEYS = new Set(['ShiftLeft', 'ShiftRight']);

export class InputState {
  constructor({ onPause, onMute, onReset } = {}) {
    this.keys = new Set();
    this.jumpQueued = false;
    this.resetQueued = false;
    this.touch = { active: false, x: 0, y: 0 };
    this.touchBoost = false;
    this.touchJump = false;
    this.onPause = onPause || (() => {});
    this.onMute = onMute || (() => {});
    this.onReset = onReset || (() => {});
    this.padPrevJump = false;
    this.padPrevBoost = false;
    this.bindKeyboard();
    this.bindTouch();
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      if (event.code === 'Space' || event.code.startsWith('Arrow') || event.code === 'Tab') {
        if (event.code !== 'Tab') event.preventDefault();
      }
      if (event.repeat) return;
      if (event.code === 'Space') this.jumpQueued = true;
      if (event.code === 'Escape' || event.code === 'KeyP') this.onPause();
      if (event.code === 'KeyM') this.onMute();
      if (event.code === 'KeyR') this.resetQueued = true;
      this.keys.add(event.code);
    });
    window.addEventListener('keyup', (event) => {
      this.keys.delete(event.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touchBoost = false;
      this.touch.active = false;
    });
  }

  bindTouch() {
    const joystick = document.getElementById('joystick');
    const knob = document.getElementById('joystickKnob');
    if (joystick && knob) {
      const update = (event) => {
        const rect = joystick.getBoundingClientRect();
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        const radius = rect.width * 0.42;
        let dx = (event.clientX - cx) / radius;
        let dy = (event.clientY - cy) / radius;
        const length = Math.hypot(dx, dy);
        if (length > 1) {
          dx /= length;
          dy /= length;
        }
        const dead = 0.1;
        const apply = (v) => (Math.abs(v) < dead ? 0 : (v - Math.sign(v) * dead) / (1 - dead));
        this.touch.x = apply(dx);
        this.touch.y = -apply(dy);
        knob.style.transform = `translate(${dx * radius}px, ${dy * radius}px)`;
      };
      joystick.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        joystick.setPointerCapture(event.pointerId);
        this.touch.active = true;
        joystick.classList.add('active');
        update(event);
      });
      joystick.addEventListener('pointermove', (event) => {
        if (!this.touch.active) return;
        event.preventDefault();
        update(event);
      });
      const end = () => {
        this.touch.active = false;
        this.touch.x = 0;
        this.touch.y = 0;
        joystick.classList.remove('active');
        knob.style.transform = 'translate(0px, 0px)';
      };
      joystick.addEventListener('pointerup', end);
      joystick.addEventListener('pointercancel', end);
      joystick.addEventListener('lostpointercapture', end);
    }

    const bindHold = (id, onDown, onUp) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        el.setPointerCapture(event.pointerId);
        el.classList.add('pressed');
        onDown();
      });
      const release = () => {
        el.classList.remove('pressed');
        onUp();
      };
      el.addEventListener('pointerup', release);
      el.addEventListener('pointercancel', release);
      el.addEventListener('lostpointercapture', release);
    };

    bindHold('boostBtn', () => { this.touchBoost = true; }, () => { this.touchBoost = false; });
    bindHold('jumpBtn', () => { this.touchJump = true; this.jumpQueued = true; }, () => { this.touchJump = false; });
  }

  get gamepad() {
    if (!navigator.getGamepads) return null;
    for (const pad of navigator.getGamepads()) {
      if (pad && pad.connected) return pad;
    }
    return null;
  }

  sample() {
    let throttle = 0;
    let steer = 0;
    let boost = false;
    let jump = this.jumpQueued;
    this.jumpQueued = false;
    let reset = this.resetQueued;
    this.resetQueued = false;

    for (const key of this.keys) {
      if (FORWARD_KEYS.has(key)) throttle += 1;
      if (BACK_KEYS.has(key)) throttle -= 1;
      if (LEFT_KEYS.has(key)) steer -= 1;
      if (RIGHT_KEYS.has(key)) steer += 1;
      if (BOOST_KEYS.has(key)) boost = true;
    }

    if (this.touch.active || Math.abs(this.touch.y) > 0.02 || Math.abs(this.touch.x) > 0.02) {
      throttle = this.touch.y;
      steer = this.touch.x;
    }
    if (this.touchBoost) boost = true;

    const pad = this.gamepad;
    if (pad) {
      const axisX = pad.axes[0] ?? 0;
      const axisY = pad.axes[1] ?? 0;
      if (Math.abs(axisX) > 0.15) steer = axisX;
      if (Math.abs(axisY) > 0.15) throttle = -axisY;
      const padJump = pad.buttons[0]?.pressed;
      const padBoost = pad.buttons[1]?.pressed || pad.buttons[7]?.pressed;
      if (padJump && !this.padPrevJump) jump = true;
      if (padBoost) boost = true;
      if (pad.buttons[3]?.pressed) reset = true;
      this.padPrevJump = padJump;
      this.padPrevBoost = padBoost;
    }

    return {
      throttle: Math.max(-1, Math.min(1, throttle)),
      steer: Math.max(-1, Math.min(1, steer)),
      boost,
      jump,
      reset,
    };
  }
}

export class Sound {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.master = null;
    this.engineGain = null;
    this.engineOsc = null;
    this.engineOsc2 = null;
    this.engineFilter = null;
    this.boostGain = null;
    this.ready = false;
    this.engineTarget = 0;
  }

  init() {
    if (this.ready) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    try {
      this.ctx = new Ctx();
    } catch {
      return;
    }
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = 0.42;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 6;
    comp.attack.value = 0.003;
    comp.release.value = 0.25;
    this.master.connect(comp);
    comp.connect(ctx.destination);

    // Reusable noise buffer.
    const length = ctx.sampleRate * 2;
    this.noiseBuffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = last * 0.86 + white * 0.14;
      data[i] = last * 2.2;
    }

    // Engine.
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 240;
    this.engineFilter.Q.value = 3.2;
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineOsc = ctx.createOscillator();
    this.engineOsc.type = 'sawtooth';
    this.engineOsc.frequency.value = 46;
    this.engineOsc2 = ctx.createOscillator();
    this.engineOsc2.type = 'square';
    this.engineOsc2.frequency.value = 92;
    const osc2Gain = ctx.createGain();
    osc2Gain.gain.value = 0.18;
    this.engineOsc.connect(this.engineFilter);
    this.engineOsc2.connect(osc2Gain);
    osc2Gain.connect(this.engineFilter);
    this.engineFilter.connect(this.engineGain);
    this.engineGain.connect(this.master);
    this.engineOsc.start();
    this.engineOsc2.start();

    // Boost hiss.
    const boostSource = ctx.createBufferSource();
    boostSource.buffer = this.noiseBuffer;
    boostSource.loop = true;
    const boostFilter = ctx.createBiquadFilter();
    boostFilter.type = 'bandpass';
    boostFilter.frequency.value = 780;
    boostFilter.Q.value = 0.85;
    this.boostGain = ctx.createGain();
    this.boostGain.gain.value = 0;
    boostSource.connect(boostFilter);
    boostFilter.connect(this.boostGain);
    this.boostGain.connect(this.master);
    boostSource.start();

    // Stadium ambience.
    const crowd = ctx.createBufferSource();
    crowd.buffer = this.noiseBuffer;
    crowd.loop = true;
    const crowdFilter = ctx.createBiquadFilter();
    crowdFilter.type = 'lowpass';
    crowdFilter.frequency.value = 420;
    const crowdGain = ctx.createGain();
    crowdGain.gain.value = 0.065;
    crowd.connect(crowdFilter);
    crowdFilter.connect(crowdGain);
    crowdGain.connect(this.master);
    crowd.start();

    this.ready = true;
    if (ctx.state === 'suspended') ctx.resume();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.42, this.ctx.currentTime, 0.05);
    }
    return this.muted;
  }

  toggleMute() {
    return this.setMuted(!this.muted);
  }

  updateEngine(speed, throttle, boosting, active) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    const target = active ? 0.018 + Math.min(1, speed / 42) * 0.035 : 0;
    this.engineTarget = target;
    this.engineGain.gain.setTargetAtTime(target, now, 0.08);
    const freq = 44 + Math.min(1, speed / 46) * 92 + Math.abs(throttle) * 8 + (boosting ? 14 : 0);
    this.engineOsc.frequency.setTargetAtTime(freq, now, 0.07);
    this.engineOsc2.frequency.setTargetAtTime(freq * 2.01, now, 0.07);
    this.engineFilter.frequency.setTargetAtTime(180 + Math.min(1, speed / 45) * 520 + (boosting ? 280 : 0), now, 0.1);
    if (this.boostGain) {
      this.boostGain.gain.setTargetAtTime(boosting && active ? 0.17 : 0, now, 0.06);
    }
  }

  tone({ freq = 220, to = null, dur = 0.2, type = 'sine', gain = 0.2, delay = 0 }) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (to) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + Math.min(0.02, dur * 0.15));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.2, gain = 0.2, freq = 900, q = 0.8, type = 'bandpass', delay = 0 }) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(t0, Math.random() * 1.5);
    src.stop(t0 + dur + 0.05);
  }

  ui() {
    this.tone({ freq: 520, to: 740, dur: 0.09, type: 'triangle', gain: 0.12 });
  }

  countdown(final = false) {
    this.tone({ freq: final ? 620 : 380, to: final ? 820 : 380, dur: final ? 0.28 : 0.12, type: 'square', gain: 0.09 });
  }

  jump() {
    this.tone({ freq: 240, to: 520, dur: 0.15, type: 'triangle', gain: 0.13 });
    this.noise({ dur: 0.12, gain: 0.08, freq: 1400 });
  }

  doubleJump() {
    this.tone({ freq: 380, to: 760, dur: 0.16, type: 'sawtooth', gain: 0.07 });
  }

  land(impact = 8) {
    const p = Math.min(1, impact / 18);
    this.tone({ freq: 100, to: 45, dur: 0.18, type: 'sine', gain: 0.12 + p * 0.12 });
    this.noise({ dur: 0.12, gain: 0.05 + p * 0.1, freq: 300, type: 'lowpass' });
  }

  hit(power = 1) {
    const p = Math.min(1.5, power);
    this.tone({ freq: 150 + p * 40, to: 48, dur: 0.16, type: 'sine', gain: 0.18 + p * 0.14 });
    this.tone({ freq: 320 + p * 90, to: 160, dur: 0.1, type: 'triangle', gain: 0.05 + p * 0.04 });
    this.noise({ dur: 0.16, gain: 0.12 + p * 0.1, freq: 900 + p * 400 });
  }

  post() {
    this.tone({ freq: 190, to: 120, dur: 0.28, type: 'square', gain: 0.1 });
    this.noise({ dur: 0.2, gain: 0.12, freq: 400, type: 'lowpass' });
  }

  wall(power = 1) {
    this.tone({ freq: 120, to: 60, dur: 0.12, type: 'sine', gain: Math.min(0.2, 0.04 + power * 0.01) });
    this.noise({ dur: 0.08, gain: Math.min(0.1, 0.01 + power * 0.004), freq: 700 });
  }

  pickup(big = false) {
    this.tone({ freq: big ? 480 : 620, to: big ? 960 : 880, dur: 0.16, type: 'triangle', gain: big ? 0.13 : 0.07 });
    if (big) this.tone({ freq: 720, to: 1440, dur: 0.22, type: 'sine', gain: 0.06, delay: 0.04 });
  }

  goal(team = 'blue', own = false) {
    if (own) {
      this.tone({ freq: 220, to: 110, dur: 0.8, type: 'sawtooth', gain: 0.12 });
      return;
    }
    const base = team === 'blue' ? 196 : 174.6;
    [1, 1.25, 1.5, 2].forEach((mult, i) => {
      this.tone({ freq: base * mult, dur: 1.35, type: 'sawtooth', gain: 0.075, delay: i * 0.02 });
    });
    this.tone({ freq: base / 2, dur: 1.5, type: 'square', gain: 0.06 });
    this.noise({ dur: 1.6, gain: 0.14, freq: 1100, q: 0.5 });
  }

  win() {
    [196, 246.9, 293.7, 392].forEach((freq, i) => {
      this.tone({ freq, dur: 0.5, type: 'triangle', gain: 0.1, delay: i * 0.1 });
    });
  }

  lose() {
    [220, 185, 146.8].forEach((freq, i) => {
      this.tone({ freq, dur: 0.55, type: 'triangle', gain: 0.09, delay: i * 0.14 });
    });
  }
}

import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { FIELD, TEAM, rand } from './constants.js';

const px = (x) => ((x + FIELD.halfLength) / (FIELD.halfLength * 2)) * 2048;
const pz = (z) => ((z + FIELD.halfWidth) / (FIELD.halfWidth * 2)) * 1310;

function fieldTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 2048;
  canvas.height = 1310;
  const ctx = canvas.getContext('2d');

  // Base and mow stripes.
  ctx.fillStyle = '#0d2b2d';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const stripe = canvas.width / 8;
  for (let i = 0; i < 8; i += 1) {
    ctx.fillStyle = i % 2 === 0 ? 'rgba(28,76,74,0.55)' : 'rgba(10,38,42,0.5)';
    ctx.fillRect(i * stripe, 0, stripe, canvas.height);
  }

  // Cool / warm end washes.
  const left = ctx.createLinearGradient(0, 0, 500, 0);
  left.addColorStop(0, 'rgba(22,72,130,0.44)');
  left.addColorStop(1, 'rgba(22,72,130,0)');
  ctx.fillStyle = left;
  ctx.fillRect(0, 0, 500, canvas.height);
  const right = ctx.createLinearGradient(canvas.width, 0, canvas.width - 500, 0);
  right.addColorStop(0, 'rgba(132,55,18,0.4)');
  right.addColorStop(1, 'rgba(132,55,18,0)');
  ctx.fillStyle = right;
  ctx.fillRect(canvas.width - 500, 0, 500, canvas.height);

  // Fine turf noise.
  for (let i = 0; i < 12000; i += 1) {
    ctx.fillStyle = Math.random() < 0.5 ? 'rgba(255,255,255,0.018)' : 'rgba(0,0,0,0.03)';
    ctx.fillRect(Math.random() * canvas.width, Math.random() * canvas.height, Math.random() * 3 + 1, Math.random() * 3 + 1);
  }

  const line = (x1, z1, x2, z2, width = 8, color = 'rgba(228,244,255,0.82)') => {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(px(x1), pz(z1));
    ctx.lineTo(px(x2), pz(z2));
    ctx.stroke();
  };
  const circle = (x, z, r, width = 8) => {
    ctx.strokeStyle = 'rgba(228,244,255,0.82)';
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.arc(px(x), pz(z), (r / (FIELD.halfLength * 2)) * 2048, 0, Math.PI * 2);
    ctx.stroke();
  };
  const rect = (x, z, w, h, width = 8) => {
    ctx.strokeStyle = 'rgba(228,244,255,0.78)';
    ctx.lineWidth = width;
    ctx.strokeRect(px(x - w / 2), pz(z - h / 2), (w / (FIELD.halfLength * 2)) * 2048, (h / (FIELD.halfWidth * 2)) * 1310);
  };

  // Boundary.
  rect(0, 0, 96, 60, 10);

  // Centre line, circle and dot.
  line(0, -30, 0, 30, 9);
  circle(0, 0, 9, 9);
  ctx.fillStyle = 'rgba(228,244,255,0.9)';
  ctx.beginPath();
  ctx.arc(px(0), pz(0), 11, 0, Math.PI * 2);
  ctx.fill();

  // Goal boxes.
  rect(-44, 0, 12, 25, 8);
  rect(44, 0, 12, 25, 8);
  rect(-47, 0, 6, 21, 7);
  rect(47, 0, 6, 21, 7);

  // Penalty arcs (clipped by canvas edges naturally).
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, canvas.width, canvas.height);
  ctx.clip();
  ctx.strokeStyle = 'rgba(228,244,255,0.64)';
  ctx.lineWidth = 7;
  ctx.beginPath();
  ctx.arc(px(-50), pz(0), (20 / 100) * 2048, -Math.PI / 2.6, Math.PI / 2.6);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(px(50), pz(0), (20 / 100) * 2048, Math.PI - Math.PI / 2.6, Math.PI + Math.PI / 2.6);
  ctx.stroke();
  ctx.restore();

  // Corner arcs.
  for (const [sx, sz] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
    ctx.strokeStyle = 'rgba(228,244,255,0.6)';
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.arc(px(sx * 48), pz(sz * 30), 42, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Faint centre emblem.
  ctx.save();
  ctx.translate(px(0), pz(0));
  ctx.globalAlpha = 0.09;
  ctx.strokeStyle = '#d9f6ff';
  ctx.lineWidth = 9;
  for (let i = 0; i < 6; i += 1) {
    const a = (Math.PI / 3) * i + Math.PI / 6;
    const x = Math.cos(a) * 168;
    const y = Math.sin(a) * 168;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.stroke();
  ctx.restore();

  // Midfield chevrons.
  ctx.strokeStyle = 'rgba(228,244,255,0.13)';
  ctx.lineWidth = 13;
  for (const dir of [-1, 1]) {
    ctx.beginPath();
    ctx.moveTo(px(dir * 5), pz(-18));
    ctx.lineTo(px(dir * 10), pz(0));
    ctx.lineTo(px(dir * 5), pz(18));
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  return texture;
}

function glowTexture() {
  const c = document.createElement('canvas');
  c.width = 128;
  c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.25, 'rgba(220,240,255,0.5)');
  g.addColorStop(1, 'rgba(160,210,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.pads = [];
    this.scoreTextures = [];
    this.goalLights = [];
    this.lampMats = [];
    this.time = 0;
    this.build();
  }

  build() {
    const scene = this.scene;

    // Environment reflections.
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    this.envMap = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environment = this.envMap;
    scene.environmentIntensity = 0.5;
    pmrem.dispose();

    this.buildSky();
    this.buildLights();
    this.buildField();
    this.buildWalls();
    this.buildGoals();
    this.buildStands();
    this.buildFloodlights();
    this.buildScoreboards();
    this.buildPads();
  }

  buildSky() {
    const scene = this.scene;
    scene.fog = new THREE.FogExp2(0x070b17, 0.0033);
    const geo = new THREE.SphereGeometry(420, 32, 20);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x040716) },
        mid: { value: new THREE.Color(0x0d1736) },
        horizon: { value: new THREE.Color(0x24183f) },
        bottom: { value: new THREE.Color(0x04050b) },
      },
      vertexShader: /* glsl */ `
        varying vec3 vPos;
        void main() {
          vPos = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 bottom;
        varying vec3 vPos;
        void main() {
          float h = normalize(vPos).y;
          vec3 col;
          if (h > 0.18) col = mix(mid, top, smoothstep(0.18, 0.9, h));
          else if (h > -0.02) col = mix(horizon, mid, smoothstep(-0.02, 0.18, h));
          else col = mix(bottom, horizon, smoothstep(-0.6, -0.02, h));
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    scene.add(new THREE.Mesh(geo, mat));

    const count = 900;
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const color = new THREE.Color();
    for (let i = 0; i < count; i += 1) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(rand(0.05, 1));
      const radius = 350;
      positions[i * 3] = Math.sin(phi) * Math.cos(theta) * radius;
      positions[i * 3 + 1] = Math.cos(phi) * radius;
      positions[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * radius;
      color.setHSL(rand(0.52, 0.68), rand(0.2, 0.8), rand(0.55, 0.95));
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    const starsGeo = new THREE.BufferGeometry();
    starsGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    starsGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const stars = new THREE.Points(
      starsGeo,
      new THREE.PointsMaterial({
        size: 1.5,
        vertexColors: true,
        transparent: true,
        opacity: 0.85,
        sizeAttenuation: true,
        depthWrite: false,
      }),
    );
    scene.add(stars);

    // Soft moon glow.
    const moonTex = glowTexture();
    const moon = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: moonTex, color: 0xcfe2ff, transparent: true, opacity: 0.5, depthWrite: false }),
    );
    moon.position.set(-160, 190, -260);
    moon.scale.setScalar(95);
    scene.add(moon);
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight(0x89b6ff, 0x0a0c14, 1.35);
    this.scene.add(hemi);

    const key = new THREE.DirectionalLight(0xd8e6ff, 2.6);
    key.position.set(30, 66, 26);
    key.castShadow = true;
    key.shadow.mapSize.set(2048, 2048);
    key.shadow.camera.left = -75;
    key.shadow.camera.right = 75;
    key.shadow.camera.top = 75;
    key.shadow.camera.bottom = -75;
    key.shadow.camera.near = 1;
    key.shadow.camera.far = 160;
    key.shadow.bias = -0.0006;
    key.shadow.normalBias = 0.03;
    this.scene.add(key);

    const rim = new THREE.DirectionalLight(0x5b7dff, 1.1);
    rim.position.set(-50, 28, -40);
    this.scene.add(rim);

    const blueSpot = new THREE.SpotLight(0x3d7bff, 320, 140, 0.72, 0.65, 1.35);
    blueSpot.position.set(-48, 40, -20);
    blueSpot.target.position.set(0, 0, 0);
    this.scene.add(blueSpot, blueSpot.target);

    const orangeSpot = new THREE.SpotLight(0xff6a24, 300, 140, 0.72, 0.65, 1.35);
    orangeSpot.position.set(48, 40, 20);
    orangeSpot.target.position.set(0, 0, 0);
    this.scene.add(orangeSpot, orangeSpot.target);
  }

  buildField() {
    const tex = fieldTexture();
    tex.anisotropy = this.renderer.capabilities.getMaxAnisotropy();
    const field = new THREE.Mesh(
      new THREE.PlaneGeometry(FIELD.halfLength * 2, FIELD.halfWidth * 2),
      new THREE.MeshStandardMaterial({
        map: tex,
        roughness: 0.68,
        metalness: 0.28,
        envMapIntensity: 0.55,
      }),
    );
    field.rotation.x = -Math.PI / 2;
    field.receiveShadow = true;
    this.scene.add(field);

    // Outer apron.
    const apron = new THREE.Mesh(
      new THREE.PlaneGeometry(FIELD.halfLength * 2 + 30, FIELD.halfWidth * 2 + 26),
      new THREE.MeshStandardMaterial({ color: 0x070b13, roughness: 0.9, metalness: 0.2 }),
    );
    apron.rotation.x = -Math.PI / 2;
    apron.position.y = -0.06;
    apron.receiveShadow = true;
    this.scene.add(apron);

    // Glowing perimeter lines.
    const stripMat = new THREE.MeshBasicMaterial({ color: 0x5fd7ff, transparent: true, opacity: 0.5 });
    const makeStrip = (w, d, x, z, color) => {
      const mat = color ? new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55 }) : stripMat;
      const strip = new THREE.Mesh(new THREE.BoxGeometry(w, 0.06, d), mat);
      strip.position.set(x, 0.04, z);
      this.scene.add(strip);
    };
    makeStrip(100, 0.25, 0, FIELD.halfWidth + 0.12);
    makeStrip(100, 0.25, 0, -FIELD.halfWidth - 0.12);
    makeStrip(0.25, 64, FIELD.halfLength + 0.12, 0);
    makeStrip(0.25, 64, -FIELD.halfLength - 0.12, 0);
  }

  buildWalls() {
    const glassMat = new THREE.MeshPhysicalMaterial({
      color: 0x8ed6ff,
      transparent: true,
      opacity: 0.055,
      roughness: 0.05,
      metalness: 0.1,
      transmission: 0,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    const frameMat = new THREE.MeshStandardMaterial({ color: 0x1b2740, metalness: 0.85, roughness: 0.35 });
    const railMat = new THREE.MeshBasicMaterial({ color: 0x7fe4ff, transparent: true, opacity: 0.6 });
    const warmRail = new THREE.MeshBasicMaterial({ color: 0xffa04a, transparent: true, opacity: 0.6 });

    const addPane = (w, h, x, y, z, ry = 0) => {
      const pane = new THREE.Mesh(new THREE.PlaneGeometry(w, h), glassMat);
      pane.position.set(x, y, z);
      pane.rotation.y = ry;
      pane.renderOrder = 2;
      this.scene.add(pane);
    };

    addPane(100, FIELD.wallHeight, 0, FIELD.wallHeight / 2, FIELD.halfWidth, 0);
    addPane(100, FIELD.wallHeight, 0, FIELD.wallHeight / 2, -FIELD.halfWidth, 0);

    for (const sx of [-1, 1]) {
      const x = sx * FIELD.halfLength;
      addPane(FIELD.halfWidth - FIELD.goalHalfWidth, FIELD.wallHeight, x, FIELD.wallHeight / 2, -(FIELD.goalHalfWidth + (FIELD.halfWidth - FIELD.goalHalfWidth) / 2), Math.PI / 2);
      addPane(FIELD.halfWidth - FIELD.goalHalfWidth, FIELD.wallHeight, x, FIELD.wallHeight / 2, FIELD.goalHalfWidth + (FIELD.halfWidth - FIELD.goalHalfWidth) / 2, Math.PI / 2);
      addPane(FIELD.goalHalfWidth * 2, FIELD.wallHeight - FIELD.goalHeight, x, FIELD.goalHeight + (FIELD.wallHeight - FIELD.goalHeight) / 2, 0, Math.PI / 2);
    }

    // Structural posts and rails.
    const postGeo = new THREE.BoxGeometry(0.28, FIELD.wallHeight, 0.28);
    const posts = [];
    for (let x = -FIELD.halfLength; x <= FIELD.halfLength + 0.01; x += 10) {
      posts.push([x, FIELD.halfWidth], [x, -FIELD.halfWidth]);
    }
    for (let z = -FIELD.halfWidth; z <= FIELD.halfWidth + 0.01; z += 8) {
      posts.push([FIELD.halfLength, z], [-FIELD.halfLength, z]);
    }
    const postMesh = new THREE.InstancedMesh(postGeo, frameMat, posts.length);
    const dummy = new THREE.Object3D();
    posts.forEach(([x, z], i) => {
      dummy.position.set(x, FIELD.wallHeight / 2, z);
      dummy.updateMatrix();
      postMesh.setMatrixAt(i, dummy.matrix);
    });
    postMesh.castShadow = false;
    this.scene.add(postMesh);

    const railGeoLong = new THREE.BoxGeometry(100.4, 0.16, 0.16);
    const railGeoShort = new THREE.BoxGeometry(0.16, 0.16, 64.4);
    for (const y of [0.35, 11, FIELD.wallHeight - 0.2]) {
      const mat = y > 11 ? railMat : frameMat;
      for (const sz of [-1, 1]) {
        const rail = new THREE.Mesh(railGeoLong, mat);
        rail.position.set(0, y, sz * FIELD.halfWidth);
        this.scene.add(rail);
      }
      for (const sx of [-1, 1]) {
        const rail = new THREE.Mesh(railGeoShort, mat);
        rail.position.set(sx * FIELD.halfLength, y, 0);
        this.scene.add(rail);
      }
    }
    // Team-coloured rails across each goal end.
    for (const [sx, mat] of [[-1, railMat], [1, warmRail]]) {
      const top = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.22, FIELD.halfWidth * 2), mat);
      top.position.set(sx * FIELD.halfLength, FIELD.wallHeight - 0.15, 0);
      this.scene.add(top);
    }

    // Vertical light blades on side walls.
    const bladeGeo = new THREE.BoxGeometry(0.1, 6.5, 0.12);
    for (let x = -40; x <= 40; x += 20) {
      for (const sz of [-1, 1]) {
        const color = sz > 0 ? 0x65d9ff : 0xff9a4d;
        const blade = new THREE.Mesh(
          bladeGeo,
          new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.5 }),
        );
        blade.position.set(x, 5.5, sz * (FIELD.halfWidth - 0.25));
        this.scene.add(blade);
      }
    }
  }

  buildGoals() {
    for (const sx of [-1, 1]) {
      const team = sx > 0 ? TEAM.orange : TEAM.blue;
      const x = sx * FIELD.halfLength;
      const accentMat = new THREE.MeshStandardMaterial({
        color: team.accent,
        emissive: team.accent,
        emissiveIntensity: 2.4,
        metalness: 0.4,
        roughness: 0.3,
      });
      const postGeo = new THREE.BoxGeometry(0.55, FIELD.goalHeight, 0.55);
      for (const sz of [-1, 1]) {
        const post = new THREE.Mesh(postGeo, accentMat);
        post.position.set(x, FIELD.goalHeight / 2, sz * FIELD.goalHalfWidth);
        post.castShadow = true;
        this.scene.add(post);
      }
      const cross = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.55, FIELD.goalHalfWidth * 2 + 0.55), accentMat);
      cross.position.set(x, FIELD.goalHeight, 0);
      cross.castShadow = true;
      this.scene.add(cross);

      // Recess floor.
      const floor = new THREE.Mesh(
        new THREE.PlaneGeometry(FIELD.goalDepth, FIELD.goalHalfWidth * 2),
        new THREE.MeshStandardMaterial({ color: team.deep, emissive: team.color, emissiveIntensity: 0.22, roughness: 0.55, metalness: 0.5 }),
      );
      floor.rotation.x = -Math.PI / 2;
      floor.position.set(x + sx * FIELD.goalDepth / 2, 0.03, 0);
      this.scene.add(floor);

      // Dark back wall.
      const back = new THREE.Mesh(
        new THREE.PlaneGeometry(FIELD.goalHalfWidth * 2, FIELD.goalHeight),
        new THREE.MeshStandardMaterial({ color: 0x05070d, roughness: 0.9, metalness: 0.2, side: THREE.DoubleSide }),
      );
      back.position.set(x + sx * (FIELD.goalDepth + 0.4), FIELD.goalHeight / 2, 0);
      back.rotation.y = Math.PI / 2;
      this.scene.add(back);

      // Nets.
      const points = [];
      const bx = x + sx * FIELD.goalDepth;
      for (let i = 0; i <= 14; i += 1) {
        const z = -FIELD.goalHalfWidth + (i / 14) * FIELD.goalHalfWidth * 2;
        points.push(bx, 0.1, z, bx, FIELD.goalHeight, z);
      }
      for (let i = 0; i <= 7; i += 1) {
        const y = (i / 7) * FIELD.goalHeight;
        points.push(bx, y, -FIELD.goalHalfWidth, bx, y, FIELD.goalHalfWidth);
      }
      // Side nets.
      for (const sz of [-1, 1]) {
        for (let i = 0; i <= 7; i += 1) {
          const y = (i / 7) * FIELD.goalHeight;
          points.push(x, y, sz * FIELD.goalHalfWidth, bx, y, sz * FIELD.goalHalfWidth);
        }
        for (let i = 0; i <= 5; i += 1) {
          const xx = x + sx * (i / 5) * FIELD.goalDepth;
          points.push(xx, 0.05, sz * FIELD.goalHalfWidth, xx, FIELD.goalHeight, sz * FIELD.goalHalfWidth);
        }
      }
      const netGeo = new THREE.BufferGeometry();
      netGeo.setAttribute('position', new THREE.Float32BufferAttribute(points, 3));
      const net = new THREE.LineSegments(
        netGeo,
        new THREE.LineBasicMaterial({ color: team.accent, transparent: true, opacity: 0.42 }),
      );
      this.scene.add(net);

      // Goal line and glow.
      const line = new THREE.Mesh(
        new THREE.BoxGeometry(0.3, 0.1, FIELD.goalHalfWidth * 2),
        new THREE.MeshBasicMaterial({ color: team.accent, transparent: true, opacity: 0.95 }),
      );
      line.position.set(x, 0.06, 0);
      this.scene.add(line);

      const light = new THREE.PointLight(team.color, 18, 34, 2);
      light.position.set(x + sx * 3.5, 4, 0);
      this.scene.add(light);
      this.goalLights.push(light);

      // Goal-mouth shimmer.
      const shimmer = new THREE.Mesh(
        new THREE.PlaneGeometry(FIELD.goalHalfWidth * 2, FIELD.goalHeight),
        new THREE.MeshBasicMaterial({
          color: team.color,
          transparent: true,
          opacity: 0.05,
          side: THREE.DoubleSide,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      );
      shimmer.position.set(x + sx * 0.3, FIELD.goalHeight / 2, 0);
      shimmer.rotation.y = Math.PI / 2;
      this.scene.add(shimmer);
    }
  }

  buildStands() {
    const tierMat = new THREE.MeshStandardMaterial({ color: 0x0a0f1b, roughness: 0.88, metalness: 0.25 });
    const crowdPalette = [
      new THREE.Color(0x0f1c35),
      new THREE.Color(0x14284c),
      new THREE.Color(0x2b1a14),
      new THREE.Color(0x2f3140),
      new THREE.Color(0x181b25),
      new THREE.Color(0x17427a),
      new THREE.Color(0x6c2c12),
      new THREE.Color(0x8c96a8),
      new THREE.Color(0x29568f),
      new THREE.Color(0xa8541e),
    ];
    const dummy = new THREE.Object3D();
    const crowdCount = 1500;
    const crowdGeo = new THREE.BoxGeometry(0.54, 1.05, 0.54);
    const crowdMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, metalness: 0.05 });
    const crowd = new THREE.InstancedMesh(crowdGeo, crowdMat, crowdCount);
    crowd.instanceMatrix.setUsage(THREE.StaticDrawUsage);

    const tiers = [];
    let index = 0;
    const color = new THREE.Color();
    const placeRows = (side) => {
      for (let row = 0; row < 6; row += 1) {
        const y = 3.3 + row * 2.4;
        const offset = 37.5 + row * 3.4;
        if (side === 'z+') tiers.push({ w: 124, h: 2.4, d: 3.6, x: 0, y, z: offset });
        if (side === 'z-') tiers.push({ w: 124, h: 2.4, d: 3.6, x: 0, y, z: -offset });
        if (side === 'x+') tiers.push({ w: 3.6, h: 2.4, d: 72, x: offset, y, z: 0 });
        if (side === 'x-') tiers.push({ w: 3.6, h: 2.4, d: 72, x: -offset, y, z: 0 });
        for (let i = 0; i < 62 && index < crowdCount; i += 1) {
          let cx = 0;
          let cz = 0;
          if (side === 'z+' || side === 'z-') {
            cx = rand(-60, 60);
            cz = (side === 'z+' ? 1 : -1) * (offset + rand(-1.3, 1.3));
          } else {
            cx = (side === 'x+' ? 1 : -1) * (offset + rand(-1.3, 1.3));
            cz = rand(-34, 34);
          }
          dummy.position.set(cx, y + 1.55, cz);
          dummy.rotation.y = rand(0, Math.PI * 2);
          const scale = rand(0.8, 1.3);
          dummy.scale.set(scale, rand(0.85, 1.25), scale);
          dummy.updateMatrix();
          crowd.setMatrixAt(index, dummy.matrix);
          color.copy(crowdPalette[Math.floor(Math.random() * crowdPalette.length)]);
          if (Math.random() < 0.04) color.setHex(Math.random() < 0.5 ? 0x5bc8ff : 0xffa64d);
          crowd.setColorAt(index, color);
          index += 1;
        }
      }
    };
    ['z+', 'z-', 'x+', 'x-'].forEach(placeRows);
    crowd.count = index;
    crowd.instanceColor.needsUpdate = true;
    this.scene.add(crowd);

    // Tier structure.
    for (const tier of tiers) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(tier.w, tier.h, tier.d), tierMat);
      mesh.position.set(tier.x, tier.y, tier.z);
      this.scene.add(mesh);
    }

    // Rail glow around the crowd base.
    const railMat = new THREE.MeshBasicMaterial({ color: 0x5cc9ff, transparent: true, opacity: 0.32 });
    const warmMat = new THREE.MeshBasicMaterial({ color: 0xff9b4d, transparent: true, opacity: 0.32 });
    for (const [z, mat] of [[1, railMat], [-1, warmMat]]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(120, 0.18, 0.18), mat);
      rail.position.set(0, 5.1, z * 35.6);
      this.scene.add(rail);
    }

    // Camera flashes / phone lights in the crowd.
    const phoneCount = 130;
    const phoneGeo = new THREE.BoxGeometry(0.12, 0.12, 0.12);
    const phoneMat = new THREE.MeshBasicMaterial({ color: 0xcfeaff });
    const phones = new THREE.InstancedMesh(phoneGeo, phoneMat, phoneCount);
    for (let i = 0; i < phoneCount; i += 1) {
      const side = Math.floor(Math.random() * 4);
      const rowY = 3.3 + Math.floor(Math.random() * 6) * 2.4 + 1.7;
      let posX = 0;
      let posZ = 0;
      if (side === 0 || side === 1) {
        posX = rand(-60, 60);
        posZ = (side === 0 ? 1 : -1) * rand(38, 55);
      } else {
        posX = (side === 2 ? 1 : -1) * rand(38, 55);
        posZ = rand(-34, 34);
      }
      dummy.position.set(posX, rowY + rand(0.4, 1), posZ);
      dummy.scale.setScalar(rand(0.7, 1.5));
      dummy.rotation.set(0, 0, 0);
      dummy.updateMatrix();
      phones.setMatrixAt(i, dummy.matrix);
    }
    this.scene.add(phones);
  }

  buildFloodlights() {
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x1b2436, metalness: 0.8, roughness: 0.4 });
    const lampMat = new THREE.MeshBasicMaterial({ color: 0xe8f5ff });
    this.lampMats.push(lampMat);
    const glow = glowTexture();
    const corners = [
      [-58, -42, 0x6fc6ff],
      [-58, 42, 0x6fc6ff],
      [58, -42, 0xffa15c],
      [58, 42, 0xffa15c],
    ];
    for (const [x, z, color] of corners) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.7, 34, 10), poleMat);
      pole.position.set(x, 17, z);
      this.scene.add(pole);

      const head = new THREE.Group();
      head.position.set(x, 34.5, z);
      head.rotation.y = Math.atan2(-x, -z);
      head.rotation.x = 0.32;
      const housing = new THREE.Mesh(new THREE.BoxGeometry(8.4, 3.4, 1.2), poleMat);
      head.add(housing);
      for (let ix = -2; ix <= 2; ix += 1) {
        for (let iy = -1; iy <= 1; iy += 1) {
          const lamp = new THREE.Mesh(new THREE.BoxGeometry(1.15, 0.7, 0.18), lampMat);
          lamp.position.set(ix * 1.45, iy * 0.95, 0.65);
          head.add(lamp);
        }
      }
      this.scene.add(head);

      const halo = new THREE.Sprite(
        new THREE.SpriteMaterial({ map: glow, color, transparent: true, opacity: 0.38, blending: THREE.AdditiveBlending, depthWrite: false }),
      );
      halo.position.set(x, 34.5, z);
      halo.scale.setScalar(22);
      this.scene.add(halo);

      // Faint volumetric shaft.
      const shaftMat = new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.018,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
      });
      const shaft = new THREE.Mesh(new THREE.ConeGeometry(13, 34, 24, 1, true), shaftMat);
      shaft.position.set(x * 0.72, 17, z * 0.72);
      shaft.rotation.z = Math.PI;
      shaft.rotation.x = 0.12;
      this.scene.add(shaft);
    }
  }

  buildScoreboards() {
    for (const sx of [-1, 1]) {
      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 512;
      const tex = new THREE.CanvasTexture(canvas);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      this.scoreTextures.push({ tex, canvas, sx });

      const mat = new THREE.MeshBasicMaterial({ map: tex });
      const screen = new THREE.Mesh(new THREE.PlaneGeometry(24, 12), mat);
      screen.position.set(sx * 59, 27.5, 0);
      screen.rotation.y = sx > 0 ? -Math.PI / 2 : Math.PI / 2;
      this.scene.add(screen);

      const frame = new THREE.Mesh(
        new THREE.BoxGeometry(25.4, 13.2, 0.8),
        new THREE.MeshStandardMaterial({ color: 0x0b1220, metalness: 0.8, roughness: 0.4 }),
      );
      frame.position.set(sx * 59.5, 27.5, 0);
      frame.rotation.y = Math.PI / 2;
      this.scene.add(frame);

      const support = new THREE.Mesh(
        new THREE.BoxGeometry(0.4, 18, 0.4),
        new THREE.MeshStandardMaterial({ color: 0x172033, metalness: 0.8, roughness: 0.4 }),
      );
      support.position.set(sx * 59.5, 36.5, 0);
      this.scene.add(support);

      this.drawScoreboard(canvas, 0, 0, '5:00', 'FIRST TO 3');
    }
  }

  drawScoreboard(canvas, blue, orange, clock, mode) {
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    const bg = ctx.createLinearGradient(0, 0, w, h);
    bg.addColorStop(0, '#071227');
    bg.addColorStop(0.5, '#050912');
    bg.addColorStop(1, '#1a0b05');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    // Frame.
    ctx.strokeStyle = 'rgba(120,190,255,0.28)';
    ctx.lineWidth = 6;
    ctx.strokeRect(8, 8, w - 16, h - 16);

    // Team bands.
    const blueGrad = ctx.createLinearGradient(0, 0, 320, 0);
    blueGrad.addColorStop(0, 'rgba(40,110,255,0.34)');
    blueGrad.addColorStop(1, 'rgba(40,110,255,0)');
    ctx.fillStyle = blueGrad;
    ctx.fillRect(0, 0, 340, h);
    const orangeGrad = ctx.createLinearGradient(w, 0, w - 340, 0);
    orangeGrad.addColorStop(0, 'rgba(255,100,26,0.34)');
    orangeGrad.addColorStop(1, 'rgba(255,100,26,0)');
    ctx.fillStyle = orangeGrad;
    ctx.fillRect(w - 340, 0, 340, h);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '700 46px "Arial Narrow", Arial, sans-serif';
    ctx.fillStyle = 'rgba(120,200,255,0.95)';
    ctx.fillText('BLUE', 170, 88);
    ctx.fillStyle = 'rgba(255,170,90,0.95)';
    ctx.fillText('ORANGE', w - 170, 88);

    ctx.font = 'italic 900 220px "Arial Black", Arial, sans-serif';
    ctx.fillStyle = '#eef7ff';
    ctx.shadowColor = '#2b7dff';
    ctx.shadowBlur = 34;
    ctx.fillText(String(blue), 170, 260);
    ctx.shadowColor = '#ff6b1e';
    ctx.fillText(String(orange), w - 170, 260);
    ctx.shadowBlur = 0;

    ctx.font = '800 92px "Arial Narrow", Arial, sans-serif';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(clock, w / 2, 246);
    ctx.font = '600 36px "Arial Narrow", Arial, sans-serif';
    ctx.fillStyle = 'rgba(190,220,255,0.62)';
    ctx.fillText(mode, w / 2, 348);

    ctx.font = '700 30px "Arial Narrow", Arial, sans-serif';
    ctx.fillStyle = 'rgba(200,230,255,0.35)';
    ctx.fillText('ROCKET DUEL  //  OMGITHUB ARENA', w / 2, 444);
  }

  updateScoreboard(blue, orange, clock, mode) {
    for (const entry of this.scoreTextures) {
      this.drawScoreboard(entry.canvas, blue, orange, clock, mode);
      entry.tex.needsUpdate = true;
    }
  }

  buildPads() {
    const padMat = new THREE.MeshStandardMaterial({
      color: 0xffc94d,
      emissive: 0xffaa22,
      emissiveIntensity: 2.2,
      metalness: 0.4,
      roughness: 0.3,
      transparent: true,
      opacity: 0.9,
    });
    const smallMat = new THREE.MeshStandardMaterial({
      color: 0x7fe0ff,
      emissive: 0x2fc4ff,
      emissiveIntensity: 2,
      metalness: 0.4,
      roughness: 0.3,
      transparent: true,
      opacity: 0.9,
    });
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xffe6a0, transparent: true, opacity: 0.5 });
    const smallRingMat = new THREE.MeshBasicMaterial({ color: 0xbdf2ff, transparent: true, opacity: 0.4 });

    const spots = [
      [-36, -22, true], [-36, 22, true], [36, -22, true], [36, 22, true],
      [-22, -10, false], [-22, 10, false], [-12, -26, false], [-12, 26, false],
      [22, -10, false], [22, 10, false], [12, -26, false], [12, 26, false],
      [0, -24, false], [0, 24, false], [44, 0, false], [-44, 0, false],
      [6, 0, false], [-6, 0, false], [0, -11, false], [0, 11, false],
    ];
    for (const [x, z, big] of spots) {
      const group = new THREE.Group();
      group.position.set(x, 0.08, z);
      const disc = new THREE.Mesh(
        new THREE.CylinderGeometry(big ? 1.8 : 0.85, big ? 2.05 : 0.95, 0.16, 6),
        big ? padMat.clone() : smallMat.clone(),
      );
      disc.castShadow = false;
      group.add(disc);
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(big ? 1.55 : 0.72, big ? 0.11 : 0.06, 8, 30),
        big ? ringMat.clone() : smallRingMat.clone(),
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = 0.12;
      group.add(ring);
      const glow = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: glowTexture(),
          color: big ? 0xffbe4d : 0x6bdcff,
          transparent: true,
          opacity: big ? 0.34 : 0.2,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      );
      glow.scale.setScalar(big ? 7 : 3.6);
      glow.position.y = 0.5;
      group.add(glow);
      this.scene.add(group);
      this.pads.push({ group, disc, ring, glow, big, x, z, active: true, timer: 0, phase: Math.random() * 6.28 });
    }
  }

  update(dt) {
    this.time += dt;
    for (const pad of this.pads) {
      if (!pad.active) {
        pad.timer -= dt;
        if (pad.timer <= 0) {
          pad.active = true;
          pad.group.visible = true;
        }
        continue;
      }
      pad.disc.rotation.y += dt * (pad.big ? 0.9 : 0.6);
      const pulse = 1 + Math.sin(this.time * 2.4 + pad.phase) * 0.06;
      pad.group.scale.setScalar(pulse);
      pad.ring.rotation.z += dt * 0.4;
      pad.glow.material.opacity = (pad.big ? 0.36 : 0.2) * (0.85 + Math.sin(this.time * 3 + pad.phase) * 0.15);
    }
    for (const light of this.goalLights) {
      light.intensity = 16 + Math.sin(this.time * 1.4) * 1.5;
    }
  }

  collectPad(pad, car) {
    if (!pad.active) return 0;
    const amount = pad.big ? 100 : 12;
    if (car.boost >= 99.5) return 0;
    pad.active = false;
    pad.group.visible = false;
    pad.timer = pad.big ? 8 : 4;
    car.boost = Math.min(100, car.boost + amount);
    return amount;
  }

  flashGoal(teamKey) {
    const light = teamKey === 'blue' ? this.goalLights[0] : this.goalLights[1];
    light.intensity = 80;
  }
}

:root {
  --blue: #4c9cff;
  --blue-bright: #7fe0ff;
  --orange: #ff8a3d;
  --orange-bright: #ffc45e;
  --ink: #eaf3ff;
  --muted: rgba(196, 220, 248, 0.62);
  --panel: rgba(6, 11, 21, 0.72);
  --line: rgba(138, 190, 255, 0.22);
  --display: "Arial Narrow", "Helvetica Neue", "Liberation Sans", Arial, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #04060c;
  color: var(--ink);
  font-family: var(--display);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  overscroll-behavior: none;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 48%, rgba(0, 0, 0, 0.52) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.18), transparent 20%, transparent 78%, rgba(0, 0, 0, 0.28));
}

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
  z-index: 0;
}

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* ---------------- HUD ---------------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.hud-top {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

.scoreboard {
  display: flex;
  align-items: stretch;
  height: 82px;
  background: linear-gradient(180deg, rgba(12, 20, 38, 0.92), rgba(4, 8, 16, 0.82));
  border: 1px solid rgba(144, 196, 255, 0.28);
  box-shadow: 0 22px 55px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  clip-path: polygon(16px 0, calc(100% - 16px) 0, 100% 16px, 100% calc(100% - 12px), calc(100% - 12px) 100%, 12px 100%, 0 calc(100% - 12px), 0 16px);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.team-block {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  width: 188px;
  padding: 0 26px;
}

.team-block.blue {
  justify-content: flex-end;
  background: linear-gradient(90deg, rgba(36, 100, 230, 0.08), rgba(54, 132, 255, 0.34));
}

.team-block.orange {
  justify-content: flex-start;
  background: linear-gradient(270deg, rgba(230, 86, 17, 0.08), rgba(255, 118, 38, 0.34));
}

.team-block.blue::after,
.team-block.orange::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  opacity: 0.9;
}

.team-block.blue::after {
  background: linear-gradient(90deg, transparent, var(--blue-bright));
  box-shadow: 0 0 14px var(--blue);
}

.team-block.orange::after {
  background: linear-gradient(270deg, transparent, var(--orange-bright));
  box-shadow: 0 0 14px var(--orange);
}

.team-label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--muted);
}

.team-block.blue .team-label {
  color: #9fcaff;
}

.team-block.orange .team-label {
  color: #ffc499;
}

.team-score {
  font-size: 48px;
  line-height: 0.9;
  font-weight: 900;
  font-style: italic;
  letter-spacing: -0.06em;
  text-shadow: 0 0 22px rgba(255, 255, 255, 0.25);
}

.match-clock {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 154px;
  padding: 6px 24px 5px;
  background: linear-gradient(180deg, rgba(2, 5, 11, 0.72), rgba(8, 14, 26, 0.45));
  border-left: 1px solid rgba(150, 200, 255, 0.16);
  border-right: 1px solid rgba(150, 200, 255, 0.16);
}

.clock {
  font-size: 30px;
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
  text-shadow: 0 0 18px rgba(100, 190, 255, 0.35);
}

.clock-mode {
  margin-top: 3px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: rgba(168, 210, 255, 0.66);
  white-space: nowrap;
}

.icon-btn {
  position: absolute;
  top: 4px;
  right: calc(22px + var(--safe-right));
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid rgba(150, 200, 255, 0.24);
  border-radius: 50%;
  background: rgba(7, 12, 22, 0.62);
  backdrop-filter: blur(10px);
  pointer-events: auto;
  transition: border-color 0.2s, background 0.2s;
}

.icon-btn:hover {
  border-color: rgba(130, 220, 255, 0.7);
  background: rgba(20, 40, 70, 0.75);
}

.icon-btn span {
  display: block;
  width: 3px;
  height: 13px;
  background: #cfe9ff;
}

.hud-bottom {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(20px + var(--safe-bottom));
  padding: 0 calc(26px + var(--safe-right)) 0 calc(26px + var(--safe-left));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.speed-readout {
  min-width: 170px;
  filter: drop-shadow(0 6px 18px rgba(0, 0, 0, 0.5));
}

.speed-value {
  display: flex;
  align-items: baseline;
  gap: 7px;
  font-size: 44px;
  font-weight: 900;
  font-style: italic;
  line-height: 0.9;
  letter-spacing: -0.05em;
  font-variant-numeric: tabular-nums;
  color: #f2f8ff;
  text-shadow: 0 0 26px rgba(80, 170, 255, 0.3);
}

.speed-value small {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.speed-label {
  display: flex;
  gap: 8px;
  margin-top: 7px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: rgba(160, 200, 240, 0.5);
}

.speed-label span {
  color: rgba(160, 200, 240, 0.3);
}

.speed-label span.hot {
  color: var(--blue-bright);
  text-shadow: 0 0 12px var(--blue);
}

.control-hint {
  display: flex;
  gap: 18px;
  margin-bottom: 2px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.13em;
  color: rgba(174, 205, 240, 0.4);
  transition: opacity 1.2s ease;
}

.control-hint b {
  color: rgba(228, 242, 255, 0.8);
  font-weight: 800;
}

.boost-meter {
  width: 258px;
  padding: 12px 15px 11px;
  background: linear-gradient(180deg, rgba(8, 14, 26, 0.78), rgba(5, 9, 17, 0.55));
  border: 1px solid rgba(150, 200, 255, 0.2);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  filter: drop-shadow(0 16px 32px rgba(0, 0, 0, 0.5));
}

.boost-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 7px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: rgba(210, 232, 255, 0.62);
}

.boost-head span:last-child {
  font-size: 22px;
  letter-spacing: 0.02em;
  color: #ffe4ad;
  line-height: 0.8;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 16px rgba(255, 160, 60, 0.5);
}

.boost-track {
  height: 13px;
  border: 1px solid rgba(255, 190, 100, 0.25);
  background: rgba(6, 10, 18, 0.9);
  transform: skewX(-16deg);
  overflow: hidden;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.7);
}

.boost-fill {
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transform: scaleX(0.34);
  background: linear-gradient(90deg, #ff7a1a, #ffb347 60%, #ffe7a0);
  box-shadow: 0 0 18px rgba(255, 150, 45, 0.8);
  transition: background 0.25s;
}

.boost-meter.full .boost-fill {
  background: linear-gradient(90deg, #38a8ff, #8be9ff 60%, #ffffff);
  box-shadow: 0 0 22px rgba(90, 220, 255, 0.9);
}

.boost-meter.full .boost-head span:last-child {
  color: #c8f4ff;
  text-shadow: 0 0 18px rgba(100, 220, 255, 0.7);
}

.boost-ticks {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  padding: 0 1px;
}

.boost-ticks i {
  display: block;
  width: 1px;
  height: 4px;
  background: rgba(255, 200, 120, 0.32);
}

/* ---------------- Banner / flash ---------------- */

.banner {
  position: fixed;
  z-index: 8;
  left: 50%;
  top: 27%;
  transform: translate(-50%, -50%) scale(0.86) skewX(-5deg);
  text-align: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.22s ease, transform 0.28s cubic-bezier(0.2, 1.4, 0.4, 1);
}

.banner.show {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1) skewX(-5deg);
}

.banner-text {
  font-size: clamp(58px, 9vw, 118px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -0.04em;
  line-height: 0.85;
  color: #f4faff;
  text-shadow: 0 0 18px rgba(120, 205, 255, 0.8), 0 0 60px rgba(50, 140, 255, 0.55), 0 8px 0 rgba(3, 8, 16, 0.4);
}

.banner-sub {
  margin-top: 12px;
  font-size: clamp(10px, 1.2vw, 14px);
  font-weight: 800;
  letter-spacing: 0.38em;
  color: rgba(190, 225, 255, 0.8);
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.7);
}

.banner.orange .banner-text {
  color: #ffe9d2;
  text-shadow: 0 0 18px rgba(255, 155, 60, 0.9), 0 0 60px rgba(255, 95, 20, 0.55), 0 8px 0 rgba(24, 6, 0, 0.4);
}

.banner.orange .banner-sub {
  color: rgba(255, 207, 155, 0.86);
}

.banner.blue .banner-text {
  color: #e6f3ff;
  text-shadow: 0 0 18px rgba(90, 190, 255, 0.9), 0 0 60px rgba(40, 120, 255, 0.6), 0 8px 0 rgba(2, 10, 24, 0.4);
}

#flash {
  position: fixed;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  background: radial-gradient(circle at center, rgba(255, 255, 255, 0.9), rgba(160, 220, 255, 0.2) 45%, transparent 75%);
  opacity: 0;
}

#flash.fire {
  animation: flashout 0.55s ease-out;
}

#flash.orange {
  background: radial-gradient(circle at center, rgba(255, 240, 210, 0.95), rgba(255, 130, 30, 0.28) 45%, transparent 75%);
}

#flash.blue {
  background: radial-gradient(circle at center, rgba(240, 250, 255, 0.95), rgba(60, 150, 255, 0.28) 45%, transparent 75%);
}

@keyframes flashout {
  0% { opacity: 0.85; }
  100% { opacity: 0; }
}

/* ---------------- Menu ---------------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  transition: opacity 0.45s ease, visibility 0.45s;
}

.menu-overlay {
  padding: calc(28px + var(--safe-top)) calc(6.5vw + var(--safe-right)) calc(24px + var(--safe-bottom)) calc(6.5vw + var(--safe-left));
  justify-content: flex-start;
  background:
    radial-gradient(ellipse at 20% 55%, rgba(6, 12, 25, 0.86), transparent 62%),
    linear-gradient(90deg, rgba(3, 6, 13, 0.94) 0%, rgba(3, 6, 13, 0.72) 34%, rgba(3, 6, 13, 0.16) 62%, transparent 100%);
}

.menu-brand {
  position: absolute;
  top: calc(26px + var(--safe-top));
  left: calc(6.5vw + var(--safe-left));
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: rgba(196, 224, 255, 0.62);
}

.brand-mark {
  color: var(--blue-bright);
  font-size: 12px;
  text-shadow: 0 0 12px var(--blue);
}

.menu-brand em {
  font-style: normal;
  padding-left: 12px;
  border-left: 1px solid rgba(150, 200, 255, 0.24);
  color: rgba(160, 200, 240, 0.36);
}

.menu-card {
  position: relative;
  width: min(600px, 47vw);
  padding: 34px 42px 30px;
  background:
    linear-gradient(135deg, rgba(10, 19, 36, 0.9), rgba(6, 11, 22, 0.58) 60%, rgba(6, 11, 22, 0.28));
  border: 1px solid rgba(130, 185, 255, 0.2);
  border-left: 2px solid rgba(105, 210, 255, 0.5);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 30px), calc(100% - 30px) 100%, 0 100%);
}

.menu-card::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 90px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--orange-bright));
  box-shadow: 0 0 18px var(--orange);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.25em;
  color: rgba(186, 218, 250, 0.7);
}

.pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--blue-bright);
  box-shadow: 0 0 10px var(--blue-bright);
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(0.75); }
}

.eyebrow-sep {
  color: rgba(160, 200, 240, 0.3);
}

.logo {
  margin: 16px 0 0;
  font-family: var(--display);
  font-size: clamp(62px, 8.2vw, 108px);
  font-weight: 900;
  font-style: italic;
  line-height: 0.76;
  letter-spacing: -0.055em;
  text-transform: uppercase;
  filter: drop-shadow(0 8px 30px rgba(0, 0, 0, 0.5));
}

.logo span {
  display: block;
  background: linear-gradient(180deg, #ffffff 8%, #b8d9ff 55%, #4c9cff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.logo .logo-accent {
  background: linear-gradient(180deg, #fff2dc 8%, #ffc45e 48%, #ff5d0a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin-left: 0.34em;
  text-shadow: 0 0 40px rgba(255, 110, 30, 0.25);
}

.tagline {
  margin: 18px 0 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: rgba(198, 220, 245, 0.66);
  text-transform: uppercase;
}

.menu-divider {
  height: 1px;
  margin: 24px 0 20px;
  background: linear-gradient(90deg, rgba(120, 190, 255, 0.36), rgba(120, 190, 255, 0.05) 70%, transparent);
}

.difficulty-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.difficulty-copy {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.difficulty-title {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: rgba(190, 220, 250, 0.62);
}

.difficulty-desc {
  font-size: 10px;
  letter-spacing: 0.05em;
  color: rgba(160, 196, 232, 0.44);
}

.difficulty-pills {
  display: flex;
  gap: 5px;
  padding: 4px;
  border: 1px solid rgba(130, 185, 255, 0.16);
  background: rgba(3, 7, 14, 0.5);
}

.diff-btn {
  padding: 8px 11px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.13em;
  color: rgba(170, 205, 240, 0.55);
  border: 1px solid transparent;
  transition: all 0.2s ease;
}

.diff-btn:hover {
  color: #e6f3ff;
  background: rgba(80, 140, 220, 0.12);
}

.diff-btn.is-active {
  color: #06101e;
  background: linear-gradient(180deg, #a9e6ff, #4c9cff);
  box-shadow: 0 0 20px rgba(70, 160, 255, 0.4);
}

.play-btn {
  position: relative;
  width: 100%;
  height: 72px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(100deg, #2f7bff 0%, #4fc3ff 58%, #9df3ff 100%);
  color: #03101e;
  font-size: 27px;
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.12em;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%);
  box-shadow: 0 14px 44px rgba(30, 130, 255, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}

.play-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, rgba(255, 255, 255, 0.6) 48%, transparent 62%);
  transform: translateX(-130%);
  transition: transform 0.55s ease;
}

.play-btn::after {
  content: "→";
  position: absolute;
  right: 24px;
  font-size: 26px;
  font-style: normal;
  transition: transform 0.2s ease;
}

.play-btn:hover {
  transform: translateY(-2px);
  filter: saturate(1.15) brightness(1.05);
  box-shadow: 0 18px 55px rgba(40, 150, 255, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.play-btn:hover::before {
  transform: translateX(130%);
}

.play-btn:hover::after {
  transform: translateX(4px);
}

.play-btn:active {
  transform: translateY(1px) scale(0.997);
}

.play-btn span {
  position: relative;
  z-index: 1;
}

.play-btn.compact {
  height: 58px;
  font-size: 20px;
  max-width: 340px;
  margin: 0 auto;
}

.play-btn.compact::after {
  display: none;
}

.menu-controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 18px;
  margin-top: 22px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.13em;
  color: rgba(160, 200, 240, 0.44);
}

.menu-controls > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.menu-controls kbd {
  display: inline-block;
  min-width: 21px;
  padding: 3px 5px;
  border: 1px solid rgba(160, 205, 250, 0.25);
  border-bottom-color: rgba(160, 205, 250, 0.45);
  border-radius: 2px;
  background: rgba(12, 22, 40, 0.7);
  color: rgba(226, 240, 255, 0.72);
  font-family: inherit;
  font-size: 7px;
  font-weight: 800;
  text-align: center;
  letter-spacing: 0.06em;
}

.menu-controls .touch-hint {
  display: none;
}

.menu-footer {
  position: absolute;
  bottom: calc(22px + var(--safe-bottom));
  left: calc(6.5vw + var(--safe-left));
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: rgba(154, 194, 236, 0.32);
}

.footer-dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(120, 170, 220, 0.4);
}

/* ---------------- Modals ---------------- */

.modal-overlay {
  justify-content: center;
  padding: 20px;
  background:
    radial-gradient(ellipse at center, rgba(8, 16, 32, 0.35), rgba(2, 5, 10, 0.82) 70%),
    rgba(2, 4, 9, 0.42);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}

.modal {
  width: min(440px, 92vw);
  padding: 32px 34px 30px;
  text-align: center;
  background: linear-gradient(160deg, rgba(11, 21, 40, 0.92), rgba(5, 10, 20, 0.88));
  border: 1px solid rgba(130, 185, 255, 0.25);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 0 100%);
}

.modal-kicker {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.3em;
  color: rgba(170, 210, 250, 0.6);
}

.modal-title {
  margin: 14px 0 8px;
  font-size: clamp(42px, 6vw, 62px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: -0.04em;
  line-height: 0.92;
  background: linear-gradient(180deg, #ffffff, #9fd8ff 60%, #3f8dff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 26px rgba(70, 160, 255, 0.32));
}

.modal-copy,
.end-sub {
  margin: 0 0 22px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: rgba(170, 205, 240, 0.52);
  text-transform: uppercase;
}

.modal-row {
  display: flex;
  gap: 10px;
  margin-top: 12px;
}

.ghost-btn {
  flex: 1;
  height: 43px;
  border: 1px solid rgba(140, 195, 255, 0.22);
  background: rgba(10, 18, 32, 0.55);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: rgba(210, 232, 255, 0.72);
  transition: all 0.2s;
}

.ghost-btn:hover {
  border-color: rgba(130, 210, 255, 0.6);
  background: rgba(20, 38, 62, 0.7);
  color: #fff;
}

.ghost-btn.wide {
  display: block;
  width: 100%;
  margin-top: 10px;
}

.end-modal {
  width: min(500px, 92vw);
}

.end-overlay.win .modal-title {
  background: linear-gradient(180deg, #ffffff, #b9e7ff 55%, #3f8dff);
  -webkit-background-clip: text;
  background-clip: text;
}

.end-overlay.lose .modal-title {
  background: linear-gradient(180deg, #ffffff, #ffd2a8 55%, #ff6318);
  -webkit-background-clip: text;
  background-clip: text;
}

.final-score {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 22px;
  margin: 18px 0 24px;
  padding: 16px 0;
  border-top: 1px solid rgba(140, 190, 255, 0.16);
  border-bottom: 1px solid rgba(140, 190, 255, 0.16);
}

.final-team {
  display: flex;
  align-items: center;
  gap: 13px;
}

.final-team span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: rgba(180, 215, 250, 0.6);
}

.final-team b {
  font-size: 42px;
  font-style: italic;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.05em;
}

.final-team.blue b {
  color: #c9e9ff;
  text-shadow: 0 0 20px rgba(70, 160, 255, 0.7);
}

.final-team.orange b {
  color: #ffd9b4;
  text-shadow: 0 0 20px rgba(255, 110, 30, 0.7);
}

.final-dash {
  color: rgba(170, 205, 240, 0.3);
  font-size: 24px;
}

/* ---------------- Touch controls ---------------- */

#touchControls {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 6;
  pointer-events: none;
}

#joystick {
  position: absolute;
  left: calc(22px + var(--safe-left));
  bottom: calc(24px + var(--safe-bottom));
  width: 132px;
  height: 132px;
  border-radius: 50%;
  border: 1px solid rgba(140, 200, 255, 0.3);
  background:
    radial-gradient(circle at 50% 50%, rgba(40, 95, 170, 0.22), rgba(4, 9, 18, 0.55) 70%),
    rgba(4, 9, 18, 0.35);
  box-shadow: inset 0 0 30px rgba(60, 140, 255, 0.12), 0 18px 40px rgba(0, 0, 0, 0.4);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(5px);
}

.joystick-ring {
  position: absolute;
  inset: 13px;
  border-radius: 50%;
  border: 1px dashed rgba(150, 205, 255, 0.16);
}

#joystickKnob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  border: 1px solid rgba(170, 225, 255, 0.7);
  background: radial-gradient(circle at 35% 30%, rgba(160, 235, 255, 0.75), rgba(40, 120, 220, 0.55) 55%, rgba(10, 30, 60, 0.8));
  box-shadow: 0 0 24px rgba(70, 180, 255, 0.45);
  pointer-events: none;
  will-change: transform;
}

.touch-buttons {
  position: absolute;
  right: calc(22px + var(--safe-right));
  bottom: calc(26px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  gap: 14px;
  pointer-events: none;
}

.touch-btn {
  pointer-events: auto;
  touch-action: none;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 9px;
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.1em;
  border: 1px solid rgba(190, 230, 255, 0.45);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.35);
  transition: transform 0.08s, filter 0.08s;
}

.touch-btn.boost {
  width: 92px;
  height: 92px;
  background: radial-gradient(circle at 35% 25%, #ffd79a, #ff8a2d 45%, #b8390a);
  color: #2a0d00;
}

.touch-btn.jump {
  width: 76px;
  height: 76px;
  background: radial-gradient(circle at 35% 25%, #c8f6ff, #45b7ff 45%, #124b96);
  color: #031526;
}

.touch-btn.pressed {
  transform: scale(0.92);
  filter: brightness(1.25);
}

@media (pointer: coarse), (max-width: 820px) {
  #touchControls {
    display: block;
  }
}

/* ---------------- Responsive ---------------- */

@media (max-width: 1100px) {
  .menu-card {
    width: min(570px, 58vw);
  }
  .control-hint {
    display: none;
  }
}

@media (max-width: 820px) {
  .menu-overlay {
    justify-content: center;
    padding: calc(64px + var(--safe-top)) 16px calc(24px + var(--safe-bottom));
    background:
      radial-gradient(ellipse at 50% 40%, rgba(8, 16, 34, 0.5), rgba(3, 6, 13, 0.86) 74%),
      rgba(3, 6, 13, 0.4);
  }

  .menu-brand {
    left: 50%;
    transform: translateX(-50%);
    top: calc(22px + var(--safe-top));
    justify-content: center;
    white-space: nowrap;
  }

  .menu-brand em {
    display: none;
  }

  .menu-card {
    width: min(520px, 94vw);
    padding: 26px 22px 24px;
    border-left-width: 1px;
  }

  .logo {
    font-size: clamp(56px, 16vw, 84px);
    line-height: 0.78;
  }

  .tagline {
    font-size: 10px;
    letter-spacing: 0.14em;
  }

  .menu-divider {
    margin: 18px 0 16px;
  }

  .difficulty-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    margin-bottom: 16px;
  }

  .difficulty-pills {
    width: 100%;
  }

  .diff-btn {
    flex: 1;
    text-align: center;
    padding: 10px 6px;
  }

  .play-btn {
    height: 62px;
    font-size: 23px;
  }

  .menu-controls {
    display: none;
  }

  .menu-controls .touch-hint {
    display: flex;
  }

  .menu-footer {
    display: none;
  }

  .scoreboard {
    height: 64px;
  }

  .team-block {
    width: 96px;
    padding: 0 10px;
    gap: 8px;
  }

  .team-label {
    font-size: 9px;
    letter-spacing: 0.16em;
  }

  .team-score {
    font-size: 34px;
  }

  .match-clock {
    min-width: 100px;
    padding: 4px 10px;
  }

  .clock {
    font-size: 22px;
  }

  .clock-mode {
    font-size: 6.5px;
    letter-spacing: 0.18em;
  }

  .icon-btn {
    top: 66px;
    right: 12px;
    width: 36px;
    height: 36px;
  }

  .icon-btn span {
    height: 11px;
  }

  .hud-bottom {
    padding: 0 14px calc(6px + var(--safe-bottom)) 14px;
  }

  .speed-readout {
    display: none;
  }

  .boost-meter {
    position: fixed;
    right: calc(14px + var(--safe-right));
    bottom: calc(196px + var(--safe-bottom));
    width: 166px;
    padding: 9px 11px;
  }

  .boost-head span:last-child {
    font-size: 17px;
  }

  .boost-track {
    height: 10px;
  }

  .modal {
    padding: 26px 22px 24px;
  }
}

@media (max-width: 430px) {
  .menu-card {
    padding: 22px 18px 20px;
  }
  .eyebrow {
    font-size: 8px;
    letter-spacing: 0.18em;
  }
  .logo {
    font-size: clamp(50px, 17vw, 72px);
  }
  .tagline {
    font-size: 9px;
  }
  .difficulty-desc {
    display: none;
  }
  .scoreboard {
    height: 58px;
  }
  .team-block {
    width: 80px;
  }
  .team-score {
    font-size: 30px;
  }
  .match-clock {
    min-width: 88px;
  }
  .clock {
    font-size: 20px;
  }
  .boost-meter {
    bottom: calc(188px + var(--safe-bottom));
  }
  #joystick {
    width: 118px;
    height: 118px;
  }
  #joystickKnob {
    width: 46px;
    height: 46px;
    margin: -23px 0 0 -23px;
  }
  .touch-btn.boost {
    width: 82px;
    height: 82px;
  }
  .touch-btn.jump {
    width: 68px;
    height: 68px;
  }
}

@media (max-height: 560px) and (orientation: landscape) {
  .menu-overlay {
    padding-top: calc(14px + var(--safe-top));
    padding-bottom: calc(12px + var(--safe-bottom));
  }
  .menu-brand {
    display: none;
  }
  .menu-card {
    width: min(640px, 78vw);
    padding: 16px 24px;
  }
  .logo {
    font-size: 48px;
  }
  .tagline,
  .menu-divider,
  .difficulty-copy {
    display: none;
  }
  .difficulty-row {
    margin: 12px 0;
  }
  .play-btn {
    height: 50px;
    font-size: 18px;
  }
  .menu-controls,
  .menu-footer {
    display: none;
  }
  .scoreboard {
    height: 52px;
  }
  .hud-top {
    top: calc(8px + var(--safe-top));
  }
  .boost-meter {
    bottom: calc(14px + var(--safe-bottom));
    right: calc(190px + var(--safe-right));
    width: 150px;
  }
  .team-block {
    width: 74px;
  }
  .team-score {
    font-size: 28px;
  }
  .match-clock {
    min-width: 78px;
  }
  .clock {
    font-size: 18px;
  }
  #joystick {
    width: 92px;
    height: 92px;
    bottom: calc(14px + var(--safe-bottom));
  }
  #joystickKnob {
    width: 38px;
    height: 38px;
    margin: -19px 0 0 -19px;
  }
  .touch-btn.boost {
    width: 66px;
    height: 66px;
  }
  .touch-btn.jump {
    width: 56px;
    height: 56px;
  }
  .touch-buttons {
    bottom: calc(14px + var(--safe-bottom));
  }
}

.rotate-hint {
  display: none;
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { Arena } from './world.js';
import { Car } from './car.js';
import { Ball } from './ball.js';
import { Effects } from './effects.js';
import { Bot } from './bot.js';
import { InputState } from './input.js';
import { Sound } from './audio.js';
import { BOT_LEVELS, CAR, FIELD, TEAM, clamp, damp } from './constants.js';

const $ = (id) => document.getElementById(id);

// ---------------------------------------------------------------- renderer

const canvas = $('game');
const isCompact = window.matchMedia('(max-width: 820px)').matches;
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: !isCompact,
  powerPreference: 'high-performance',
  stencil: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isCompact ? 1.7 : 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 600);
camera.position.set(62, 34, 48);

const arena = new Arena(scene, renderer);
const effects = new Effects(scene, renderer);
const ball = new Ball(scene);
const player = new Car(scene, TEAM.blue, { isBot: false });
const botCar = new Car(scene, TEAM.orange, { isBot: true, accent: 0xffd75e });
const bot = new Bot('pro');
const sound = new Sound();

player.onEvent = (type, power) => {
  if (type === 'jump') sound.jump();
  else if (type === 'double') sound.doubleJump();
  else if (type === 'land') sound.land(power);
};
botCar.onEvent = (type, power) => {
  if (type === 'land' && power > 9) sound.land(power * 0.45);
};

const composer = new EffectComposer(renderer);
composer.setSize(window.innerWidth, window.innerHeight);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), isCompact ? 0.5 : 0.68, 0.62, 0.78);
composer.addPass(bloom);
composer.addPass(new OutputPass());

ball.onEvent = (type, power) => {
  if (type === 'bounce') {
    const volume = clamp(power / 45, 0.1, 1);
    sound.hit(volume * 0.55);
    shake = Math.max(shake, volume * 0.14);
  } else if (type === 'wall') {
    sound.wall(power);
    shake = Math.max(shake, clamp(power / 90, 0, 0.2));
  }
};

// ---------------------------------------------------------------- UI refs

const ui = {
  hud: $('hud'),
  menu: $('menu'),
  pause: $('pause'),
  end: $('end'),
  scoreBlue: $('scoreBlue'),
  scoreOrange: $('scoreOrange'),
  clock: $('clock'),
  modeLabel: $('modeLabel'),
  boostFill: $('boostFill'),
  boostValue: $('boostValue'),
  boostMeter: document.querySelector('.boost-meter'),
  speedValue: $('speedValue'),
  speedTag: $('speedTag'),
  banner: $('banner'),
  bannerText: $('bannerText'),
  bannerSub: $('bannerSub'),
  flash: $('flash'),
  startBtn: $('startBtn'),
  pauseBtn: $('pauseBtn'),
  resumeBtn: $('resumeBtn'),
  restartBtn: $('restartBtn'),
  quitBtn: $('quitBtn'),
  againBtn: $('againBtn'),
  menuBtn: $('menuBtn'),
  endKicker: $('endKicker'),
  endTitle: $('endTitle'),
  endSub: $('endSub'),
  endScoreBlue: $('endScoreBlue'),
  endScoreOrange: $('endScoreOrange'),
  difficultyDesc: $('difficultyDesc'),
  diffButtons: [...document.querySelectorAll('.diff-btn')],
  controlHint: $('controlHint'),
};

const DIFFICULTY_COPY = {
  rookie: 'Gentle pressure. Room to learn the arena.',
  pro: 'Balanced pressure, sharp shots.',
  allstar: 'Ruthless rotations and supersonic clears.',
};

// ---------------------------------------------------------------- game state

let mode = 'menu';
let scoreBlue = 0;
let scoreOrange = 0;
let matchTime = 180;
let overtime = false;
let goalTimer = 0;
let kickoffTimer = 0;
let paused = false;
let difficulty = 'pro';
let shake = 0;
let menuAngle = 0.72;
let endAngle = 0;
let cameraMode = 'menu';
let hudAccumulator = 0;
let bannerTimeout = 0;
let hintTimer = 0;
let lastScorer = 'blue';
let frameCount = 0;

const playerForward = new THREE.Vector3();
const camDesired = new THREE.Vector3();
const camLook = new THREE.Vector3();
const tmpA = new THREE.Vector3();
const tmpB = new THREE.Vector3();
const tmpC = new THREE.Vector3();
const shakeOffset = new THREE.Vector3();

const input = new InputState({
  onPause: () => togglePause(),
  onMute: () => {
    if (!sound.ready) return;
    sound.toggleMute();
  },
  onReset: () => {
    // handled by sample() so it only triggers once.
  },
});

// ---------------------------------------------------------------- helpers

function clockText() {
  if (overtime) return 'OT';
  const total = Math.max(0, Math.ceil(matchTime));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

function modeText() {
  return overtime ? 'OVERTIME • NEXT GOAL WINS' : 'FIRST TO 3';
}

function updateHud(force = false) {
  if (!force && mode === 'menu') return;
  ui.scoreBlue.textContent = String(scoreBlue);
  ui.scoreOrange.textContent = String(scoreOrange);
  ui.clock.textContent = clockText();
  ui.modeLabel.textContent = modeText();
  const boost = clamp(player.boost / 100, 0, 1);
  ui.boostFill.style.transform = `scaleX(${boost})`;
  ui.boostValue.textContent = String(Math.round(player.boost));
  ui.boostMeter.classList.toggle('full', player.boost > 99.5);
  ui.speedValue.textContent = String(Math.round(player.speed * 3.6));
  const hot = player.speed > 34;
  ui.speedTag.textContent = hot ? 'MAX' : player.boosting ? 'BOOSTING' : 'READY';
  ui.speedTag.classList.toggle('hot', hot || player.boosting);
}

function showBanner(text, sub = '', tone = '', duration = 1.05) {
  window.clearTimeout(bannerTimeout);
  ui.bannerText.textContent = text;
  ui.bannerSub.textContent = sub;
  ui.banner.className = `banner show ${tone}`.trim();
  bannerTimeout = window.setTimeout(() => {
    ui.banner.classList.remove('show');
  }, duration * 1000);
}

function flash(tone = '') {
  ui.flash.className = tone;
  void ui.flash.offsetWidth;
  ui.flash.classList.add('fire');
}

ui.flash.addEventListener('animationend', () => ui.flash.classList.remove('fire'));

function applyDifficulty(level, announce = false) {
  difficulty = level;
  bot.setLevel(level);
  const skill = BOT_LEVELS[level];
  botCar.maxSpeed = skill.maxSpeed;
  botCar.boostSpeed = skill.boostSpeed;
  botCar.accelScale = skill.accelScale;
  ui.difficultyDesc.textContent = DIFFICULTY_COPY[level];
  for (const button of ui.diffButtons) {
    button.classList.toggle('is-active', button.dataset.level === level);
  }
  if (announce && mode === 'playing') showBanner(skill.label.toUpperCase(), 'BOT DIFFICULTY', '', 0.9);
}

function setHudVisible(visible) {
  ui.hud.classList.toggle('is-hidden', !visible);
  ui.hud.setAttribute('aria-hidden', String(!visible));
}

function showOverlay(element, visible) {
  element.classList.toggle('is-hidden', !visible);
  element.setAttribute('aria-hidden', String(!visible));
}

function snapCamera() {
  playerForward.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  camera.position.copy(player.pos).addScaledVector(playerForward, -11.2);
  camera.position.y += 4.6;
  camera.lookAt(player.pos.x + playerForward.x * 10, player.pos.y + 2.4, player.pos.z + playerForward.z * 10);
  camera.fov = 70;
  camera.updateProjectionMatrix();
}

function resetPads() {
  for (const pad of arena.pads) {
    pad.active = true;
    pad.timer = 0;
    pad.group.visible = true;
  }
}

// ---------------------------------------------------------------- match flow

function resetKickoff(first = false) {
  ball.reset(0, 0);
  player.reset(-30, 0, 0, CAR.boostStart);
  const skill = BOT_LEVELS[difficulty];
  botCar.maxSpeed = skill.maxSpeed;
  botCar.boostSpeed = skill.boostSpeed;
  botCar.accelScale = skill.accelScale;
  botCar.reset(30, 0, Math.PI, skill.boostStart);
  bot.reset();
  resetPads();
  kickoffTimer = 1.05;
  mode = 'playing';
  cameraMode = 'chase';
  shake = 0;
  snapCamera();
  showBanner('GO!', first ? 'FIRST TO 3 • 3:00' : 'KICKOFF', '', 0.85);
  sound.countdown(true);
  updateHud(true);
}

function startMatch() {
  sound.init();
  sound.ui();
  applyDifficulty(difficulty);
  scoreBlue = 0;
  scoreOrange = 0;
  matchTime = 180;
  overtime = false;
  goalTimer = 0;
  paused = false;
  lastScorer = 'blue';
  arena.updateScoreboard(0, 0, '3:00', 'FIRST TO 3');
  showOverlay(ui.menu, false);
  showOverlay(ui.end, false);
  showOverlay(ui.pause, false);
  setHudVisible(true);
  hintTimer = 9;
  ui.controlHint.style.opacity = '1';
  resetKickoff(true);
  updateHud(true);
}

function onGoal(teamKey) {
  if (mode !== 'playing') return;
  mode = 'goal';
  lastScorer = teamKey;
  if (teamKey === 'blue') scoreBlue += 1;
  else scoreOrange += 1;

  goalTimer = 2.35;
  cameraMode = 'goal';
  shake = 1;
  const scoringPlayer = teamKey === 'blue';
  const burstColor = scoringPlayer ? TEAM.blue.color : TEAM.orange.color;
  const accent = scoringPlayer ? TEAM.blue.accent : TEAM.orange.accent;
  effects.goalBurst(tmpA.copy(ball.pos), burstColor, accent);
  flash(scoringPlayer ? 'blue' : 'orange');
  arena.flashGoal(teamKey);
  arena.updateScoreboard(scoreBlue, scoreOrange, clockText(), modeText());
  showBanner('GOAL!', scoringPlayer ? 'YOU SCORE' : 'BOT SCORES', scoringPlayer ? 'blue' : 'orange', 1.9);
  if (scoringPlayer) sound.goal('blue');
  else sound.goal('orange');
  updateHud(true);
}

function endMatch() {
  if (mode === 'ended') return;
  mode = 'ended';
  cameraMode = 'orbit';
  endAngle = Math.atan2(camera.position.z, camera.position.x);
  const won = scoreBlue > scoreOrange;
  ui.end.classList.toggle('win', won);
  ui.end.classList.toggle('lose', !won);
  ui.endKicker.textContent = overtime ? 'GOLDEN GOAL • MATCH COMPLETE' : 'MATCH COMPLETE';
  ui.endTitle.textContent = won ? 'VICTORY' : 'DEFEAT';
  ui.endSub.textContent = won
    ? scoreOrange === 0
      ? 'A flawless clean sheet in the neon arena.'
      : 'The arena is yours. One more run?'
    : 'The bot found the gaps. Time for a rematch.';
  ui.endScoreBlue.textContent = String(scoreBlue);
  ui.endScoreOrange.textContent = String(scoreOrange);
  showOverlay(ui.end, true);
  showBanner(won ? 'VICTORY' : 'DEFEAT', `${scoreBlue} — ${scoreOrange}`, won ? 'blue' : 'orange', 2);
  if (won) sound.win();
  else sound.lose();
  arena.updateScoreboard(scoreBlue, scoreOrange, clockText(), modeText());
}

function togglePause() {
  if (mode === 'playing') {
    paused = true;
    showOverlay(ui.pause, true);
    sound.updateEngine(0, 0, false, false);
  } else if (mode === 'playing' && paused) {
    paused = false;
    showOverlay(ui.pause, false);
  } else if (paused) {
    paused = false;
    showOverlay(ui.pause, false);
  }
}

function resumeMatch() {
  paused = false;
  showOverlay(ui.pause, false);
  sound.init();
}

function quitToMenu() {
  mode = 'menu';
  paused = false;
  scoreBlue = 0;
  scoreOrange = 0;
  matchTime = 180;
  overtime = false;
  showOverlay(ui.menu, true);
  showOverlay(ui.end, false);
  showOverlay(ui.pause, false);
  setHudVisible(false);
  cameraMode = 'menu';
  ball.reset(0, 0);
  player.reset(-30, 0, 0, CAR.boostStart);
  botCar.reset(30, 0, Math.PI, BOT_LEVELS[difficulty].boostStart);
  resetPads();
  sound.updateEngine(0, 0, false, false);
  menuAngle = 0.72;
}

function resetPlayerCar() {
  if (mode !== 'playing' || paused) return;
  const boost = player.boost;
  player.reset(-30, 0, 0, boost);
  effects.emit(player.pos, { count: 22, color: TEAM.blue.accent, speed: 8, spread: 4, life: 0.5, size: 0.3, gravity: 3 });
  snapCamera();
}

// ---------------------------------------------------------------- physics

function collideCarBall(car) {
  const R = ball.radius;
  const hx = 2.58;
  const hy = 0.98;
  const hz = 1.34;
  const cos = Math.cos(car.yaw);
  const sin = Math.sin(car.yaw);
  const dx = ball.pos.x - car.pos.x;
  const dy = ball.pos.y - car.pos.y;
  const dz = ball.pos.z - car.pos.z;
  const lx = dx * cos - dz * sin;
  const ly = dy;
  const lz = dx * sin + dz * cos;
  const cx = clamp(lx, -hx, hx);
  const cy = clamp(ly, -hy, hy);
  const cz = clamp(lz, -hz, hz);
  const ddx = lx - cx;
  const ddy = ly - cy;
  const ddz = lz - cz;
  const dist = Math.hypot(ddx, ddy, ddz);
  if (dist >= R) return false;

  let nx;
  let ny;
  let nz;
  if (dist < 0.0001) {
    // Ball centre is inside the chassis: eject along the nose.
    nx = lx >= 0 ? 1 : -1;
    ny = 0.35;
    nz = lz >= 0 ? 0.2 : -0.2;
  } else {
    nx = ddx / dist;
    ny = ddy / dist;
    nz = ddz / dist;
  }
  const nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen;
  ny /= nLen;
  nz /= nLen;

  // Back to world space.
  const wx = nx * cos + nz * sin;
  const wy = ny;
  const wz = -nx * sin + nz * cos;
  const penetration = R - dist + 0.01;
  ball.pos.x += wx * penetration;
  ball.pos.y += wy * penetration;
  ball.pos.z += wz * penetration;

  const normal = tmpA.set(wx, wy, wz);
  const carSpeed = car.vel.length();
  const approach = Math.max(0, -tmpB.copy(ball.vel).sub(car.vel).dot(normal));
  const power = 9 + carSpeed * 0.95 + approach * 0.5 + (car.boosting ? 5 : 0);
  const lift = normal.y < 0.25 && carSpeed > 14 ? 2.2 + carSpeed * 0.075 : 0;
  ball.vel.multiplyScalar(0.34);
  ball.vel.addScaledVector(normal, power);
  ball.vel.addScaledVector(car.vel, 0.42);
  ball.vel.y += lift;
  if (ball.vel.length() > 86) ball.vel.setLength(86);
  ball.pos.y = Math.max(ball.pos.y, R);

  if (car.hitCooldown <= 0) {
    car.hitCooldown = 0.11;
    const playerHit = car === player;
    sound.hit(power / 34 + (playerHit ? 0.2 : 0.05));
    shake = Math.max(shake, clamp(power / 140, 0.08, 0.9));
    const color = playerHit ? TEAM.blue.accent : TEAM.orange.accent;
    effects.emit(ball.pos, {
      count: Math.round(6 + power * 0.55),
      color: 0xffffff,
      speed: 9 + power * 0.22,
      spread: 5,
      life: 0.42,
      size: 0.32,
      gravity: 3,
      direction: normal,
      jitter: 0.6,
    });
    effects.emit(ball.pos, {
      count: Math.round(4 + power * 0.3),
      color,
      speed: 7,
      spread: 4,
      life: 0.5,
      size: 0.24,
      gravity: 1,
      jitter: 0.5,
    });
    if (power > 34) {
      effects.ring(tmpC.copy(ball.pos).setY(Math.max(R, ball.pos.y - R + 0.1)), color, 5 + power * 0.08, 0.45);
    }
  }
  return true;
}

function collideCars() {
  const dx = botCar.pos.x - player.pos.x;
  const dz = botCar.pos.z - player.pos.z;
  const dy = botCar.pos.y - player.pos.y;
  const dist = Math.hypot(dx, dz);
  const minDist = 3.35;
  if (dist > 0.001 && dist < minDist && Math.abs(dy) < 2.6) {
    const nx = dx / dist;
    const nz = dz / dist;
    const overlap = minDist - dist;
    player.pos.x -= nx * overlap * 0.5;
    player.pos.z -= nz * overlap * 0.5;
    botCar.pos.x += nx * overlap * 0.5;
    botCar.pos.z += nz * overlap * 0.5;
    const relative = (botCar.vel.x - player.vel.x) * nx + (botCar.vel.z - player.vel.z) * nz;
    if (relative < 0) {
      const impulse = relative * 0.55;
      player.vel.x += nx * impulse;
      player.vel.z += nz * impulse;
      botCar.vel.x -= nx * impulse;
      botCar.vel.z -= nz * impulse;
      if (Math.abs(relative) > 8) {
        sound.land(Math.abs(relative) * 0.6);
        shake = Math.max(shake, 0.16);
        effects.emit(tmpA.copy(player.pos).lerp(botCar.pos, 0.5), {
          count: 14,
          color: 0xffe0a0,
          speed: 6,
          spread: 4,
          life: 0.35,
          size: 0.26,
          gravity: 4,
        });
      }
    }
  }
}

function checkPads() {
  for (const pad of arena.pads) {
    if (!pad.active) continue;
    const radius = pad.big ? 2.4 : 1.3;
    for (const car of [player, botCar]) {
      if (car.pos.y > 4) continue;
      const dx = car.pos.x - pad.x;
      const dz = car.pos.z - pad.z;
      if (dx * dx + dz * dz < radius * radius) {
        const amount = arena.collectPad(pad, car);
        if (amount > 0) {
          const color = pad.big ? 0xffc94d : 0x7fe0ff;
          effects.emit(tmpA.set(pad.x, 0.7, pad.z), {
            count: pad.big ? 30 : 12,
            color,
            speed: pad.big ? 10 : 6,
            spread: 3,
            life: 0.55,
            size: pad.big ? 0.38 : 0.24,
            direction: new THREE.Vector3(0, 1, 0),
            jitter: 0.4,
          });
          if (car === player) {
            sound.pickup(pad.big);
            updateHud(true);
          }
        }
      }
    }
  }
}

function checkGoal() {
  const inMouth = Math.abs(ball.pos.z) < FIELD.goalHalfWidth - 0.3 && ball.pos.y < FIELD.goalHeight - 0.2;
  if (!inMouth) return;
  if (ball.pos.x > FIELD.halfLength + 0.35) onGoal('blue');
  else if (ball.pos.x < -FIELD.halfLength - 0.35) onGoal('orange');
}

// ---------------------------------------------------------------- camera

function updateCamera(dt) {
  if (mode === 'menu') {
    menuAngle += dt * 0.065;
    const radiusX = 84;
    const radiusZ = 66;
    camera.position.x = Math.cos(menuAngle) * radiusX;
    camera.position.z = Math.sin(menuAngle) * radiusZ;
    camera.position.y = 37 + Math.sin(menuAngle * 0.8) * 2.4;
    camera.lookAt(0, 4.5, 0);
    camera.fov = damp(camera.fov, 56, 3, dt);
    camera.updateProjectionMatrix();
    return;
  }

  if (mode === 'ended') {
    endAngle += dt * 0.09;
    camera.position.x = Math.cos(endAngle) * 68;
    camera.position.z = Math.sin(endAngle) * 58;
    camera.position.y = 30;
    camera.lookAt(0, 3, 0);
    camera.fov = damp(camera.fov, 60, 2, dt);
    camera.updateProjectionMatrix();
    applyShake(dt);
    return;
  }

  if (cameraMode === 'goal' && ball.pos) {
    camDesired.set(ball.pos.x + (ball.pos.x > 0 ? -17 : 17), 9.5, ball.pos.z + 13);
    camLook.copy(ball.pos).add(tmpA.set(0, 2.2, 0));
    camera.position.lerp(camDesired, 1 - Math.exp(-3.2 * dt));
    camera.lookAt(camLook);
    camera.fov = damp(camera.fov, 66, 3, dt);
    camera.updateProjectionMatrix();
    applyShake(dt);
    return;
  }

  playerForward.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  const speed = player.speed;
  const back = 11.4 + clamp(speed / 50, 0, 1) * 1.7;
  camDesired.copy(player.pos).addScaledVector(playerForward, -back);
  camDesired.y += 4.55;
  camDesired.x = clamp(camDesired.x, -54, 54);
  camDesired.z = clamp(camDesired.z, -36, 36);
  camDesired.y = clamp(camDesired.y, 2.6, 30);

  const lookAhead = 10 + clamp(speed / 50, 0, 1) * 3.5;
  camLook.copy(player.pos).addScaledVector(playerForward, lookAhead);
  camLook.y += 2.1;
  camLook.addScaledVector(player.vel, 0.045);

  camera.position.lerp(camDesired, 1 - Math.exp(-7.5 * dt));
  camera.lookAt(camLook);
  const fovTarget = 70 + clamp(speed / 51, 0, 1) * 8 + (player.boosting ? 3.5 : 0);
  camera.fov = damp(camera.fov, fovTarget, 4.5, dt);
  camera.updateProjectionMatrix();
  applyShake(dt);
}

function applyShake(dt) {
  shake = Math.max(0, shake - dt * 2.4);
  if (shake <= 0.001) return;
  const amount = shake * 0.55;
  shakeOffset.set(
    (Math.random() - 0.5) * amount,
    (Math.random() - 0.5) * amount * 0.8,
    (Math.random() - 0.5) * amount,
  );
  camera.position.add(shakeOffset);
}

// ---------------------------------------------------------------- updates

function updatePlaying(dt) {
  if (kickoffTimer > 0) kickoffTimer -= dt;

  if (!overtime) {
    matchTime -= dt;
    if (matchTime <= 0) {
      matchTime = 0;
      if (scoreBlue === scoreOrange) {
        overtime = true;
        showBanner('OVERTIME', 'NEXT GOAL WINS', '', 2.1);
        sound.countdown(true);
        arena.updateScoreboard(scoreBlue, scoreOrange, clockText(), modeText());
      } else {
        endMatch();
        return;
      }
    }
  }

  const controls = input.sample();
  if (controls.reset) resetPlayerCar();
  player.update(dt, controls, effects);
  const botControls = bot.update(dt, { ball, botCar });
  botCar.update(dt, botControls, effects);

  ball.update(dt, effects, true);

  collideCarBall(player);
  collideCarBall(botCar);
  collideCars();
  checkPads();

  if (mode !== 'playing') return;
  checkGoal();
  if (mode !== 'playing') return;

  if (hintTimer > 0) {
    hintTimer -= dt;
    if (hintTimer <= 0) ui.controlHint.style.opacity = '0';
  }

  hudAccumulator += dt;
  if (hudAccumulator > 0.06) {
    hudAccumulator = 0;
    updateHud();
  }
  updateCamera(dt);
  sound.updateEngine(player.speed, controls.throttle, player.boosting, true);
}

function updateGoalState(dt) {
  goalTimer -= dt;
  const idle = { throttle: 0, steer: 0, boost: false, jump: false };
  player.update(dt, idle, effects);
  botCar.update(dt, idle, effects);
  ball.update(dt, effects, false);
  updateCamera(dt);
  sound.updateEngine(player.speed, 0, false, false);
  if (goalTimer <= 0) {
    const matchOver = scoreBlue >= 3 || scoreOrange >= 3 || overtime;
    if (matchOver) {
      endMatch();
    } else {
      cameraMode = 'chase';
      resetKickoff(false);
    }
  }
}

function updateEnded(dt) {
  const idle = { throttle: 0, steer: 0, boost: false, jump: false };
  player.update(dt, idle, effects);
  botCar.update(dt, idle, effects);
  ball.update(dt, effects, false);
  updateCamera(dt);
  sound.updateEngine(player.speed, 0, false, false);
}

// ---------------------------------------------------------------- loop

let lastTime = performance.now();

function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.034, Math.max(0.0001, (now - lastTime) / 1000));
  lastTime = now;
  frameCount += 1;

  arena.update(dt);

  if (paused) {
    sound.updateEngine(0, 0, false, false);
    composer.render();
    return;
  }

  if (mode === 'menu') {
    menuAngle += 0;
    ball.update(dt, effects, false);
    player.update(dt, { throttle: 0, steer: 0, boost: false, jump: false }, effects);
    botCar.update(dt, { throttle: 0, steer: 0, boost: false, jump: false }, effects);
    effects.update(dt);
    updateCamera(dt);
    sound.updateEngine(0, 0, false, false);
  } else if (mode === 'playing') {
    updatePlaying(dt);
    effects.update(dt);
  } else if (mode === 'goal') {
    updateGoalState(dt);
    effects.update(dt);
  } else if (mode === 'ended') {
    updateEnded(dt);
    effects.update(dt);
  }

  composer.render();
}

// ---------------------------------------------------------------- wiring

ui.startBtn.addEventListener('click', startMatch);
ui.pauseBtn.addEventListener('click', () => {
  if (mode !== 'playing' || paused) return;
  paused = true;
  showOverlay(ui.pause, true);
  sound.updateEngine(0, 0, false, false);
});
ui.resumeBtn.addEventListener('click', resumeMatch);
ui.restartBtn.addEventListener('click', () => {
  sound.ui();
  showOverlay(ui.pause, false);
  paused = false;
  startMatch();
});
ui.quitBtn.addEventListener('click', () => {
  sound.ui();
  quitToMenu();
});
ui.againBtn.addEventListener('click', () => {
  sound.ui();
  startMatch();
});
ui.menuBtn.addEventListener('click', () => {
  sound.ui();
  quitToMenu();
});

for (const button of ui.diffButtons) {
  button.addEventListener('click', () => {
    applyDifficulty(button.dataset.level, false);
    sound.init();
    sound.ui();
  });
}

window.addEventListener('keydown', (event) => {
  if (event.code === 'Escape' || event.code === 'KeyP') {
    if (mode === 'playing') {
      if (paused) resumeMatch();
      else {
        paused = true;
        showOverlay(ui.pause, true);
        sound.updateEngine(0, 0, false, false);
      }
    } else if (paused) {
      resumeMatch();
    }
  }
  if (event.code === 'Enter' && mode === 'menu') startMatch();
  if (event.code === 'Enter' && mode === 'ended') startMatch();
});

// InputState already listens for Escape; remove duplicate behaviour by
