window.addEventListener('keydown', (event) => {
  if (event.code === 'Escape' || event.code === 'KeyP') {
    // The handler above owns this; prevent the InputState callback from
    // double-toggling by letting only the paused-state transition pass.
    event.stopImmediatePropagation();
  }
}, true);

document.addEventListener('visibilitychange', () => {
  if (document.hidden && mode === 'playing' && !paused) {
    paused = true;
    showOverlay(ui.pause, true);
    sound.updateEngine(0, 0, false, false);
  }
});

window.addEventListener('resize', () => {
  const width = window.innerWidth;
  const height = window.innerHeight;
  camera.aspect = width / height;
  camera.updateProjectionMatrix();
  renderer.setSize(width, height);
  composer.setSize(width, height);
