import * as THREE from 'three';
import { BOT_LEVELS, FIELD, clamp, rand, wrapAngle } from './constants.js';

export class Bot {
  constructor(level = 'pro') {
    this.setLevel(level);
    this.target = new THREE.Vector3();
    this.tmp = new THREE.Vector3();
    this.thinkTimer = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.jumpCooldown = 0;
    this.boostTimer = 0;
    this.mode = 'attack';
    this.strike = false;
  }

  setLevel(level) {
    this.level = level;
    this.skill = BOT_LEVELS[level] ?? BOT_LEVELS.pro;
  }

  reset() {
    this.thinkTimer = 0;
    this.stuckTimer = 0;
    this.reverseTimer = 0;
    this.jumpCooldown = 0;
    this.boostTimer = 0;
    this.mode = 'attack';
    this.strike = false;
  }

  chooseTarget(game, car) {
    const ball = game.ball;
    const skill = this.skill;
    const lead = 0.14 + (1 - skill.reaction) * 0.16;
    const predicted = this.tmp.copy(ball.pos).addScaledVector(ball.vel, lead);
    predicted.y = 0;
    predicted.x = clamp(predicted.x, -46, 46);
    predicted.z = clamp(predicted.z, -29, 29);

    const ballX = predicted.x;
    const ballZ = predicted.z;
    const botX = car.pos.x;
    const botZ = car.pos.z;
    const distanceToBall = Math.hypot(ballX - botX, ballZ - botZ);
    const goalX = -FIELD.halfLength + 4;

    // How far behind the ball (relative to the goal we attack) are we?
    const behind = botX - ballX;
    let target;

    if (ballX > 36 && ball.vel.x > 2) {
      // Emergency defence: get between the ball and our own net.
      this.mode = 'defend';
      this.strike = false;
      target = new THREE.Vector3(ballX + 5.5, 0, ballZ * 0.55);
      if (target.x > 45) target.x = 45;
    } else if (behind > -1.6) {
      // Correct side. Strike through the ball when close, otherwise set up.
      if (distanceToBall < 14) {
        this.mode = 'strike';
        this.strike = true;
        const shotZ = clamp(ballZ - (ballZ - 0) * 0.18, -8, 8);
        target = new THREE.Vector3(ballX + (goalX - ballX) * 0.12, 0, ballZ + (shotZ - ballZ) * 0.25);
        // Aim at a point just through the ball toward goal.
        const dir = new THREE.Vector3(goalX - ballX, 0, -ballZ);
        dir.normalize();
        target.copy(predicted).addScaledVector(dir, 3.2);
      } else {
        this.mode = 'approach';
        this.strike = false;
        target = new THREE.Vector3(ballX + 5, 0, ballZ + (car.pos.z > ballZ ? 1.8 : -1.8));
      }
    } else {
      // Wrong side: loop wide around the ball rather than turning into our net.
      this.mode = 'loop';
      this.strike = false;
      const side = botZ >= ballZ ? 1 : -1;
      target = new THREE.Vector3(ballX + 8, 0, ballZ + side * 10.5);
    }

    // If the ball is airborne, shadow the landing zone rather than sitting under it.
    if (ball.pos.y > 5 && ball.vel.y < 0) {
      target.x = ballX + ball.vel.x * 0.45;
      target.z = ballZ + ball.vel.z * 0.45;
    }

    target.x = clamp(target.x, -46, 46);
    target.z = clamp(target.z, -29, 29);
    if (this.mode !== 'strike') {
      target.x += rand(-skill.aimNoise, skill.aimNoise);
      target.z += rand(-skill.aimNoise, skill.aimNoise);
    }
    this.target.copy(target);
  }

  update(dt, game) {
    const car = game.botCar;
    const ball = game.ball;
    this.thinkTimer -= dt;
    this.jumpCooldown -= dt;
    this.boostTimer -= dt;

    if (this.thinkTimer <= 0) {
      this.thinkTimer = this.skill.reaction * rand(0.8, 1.25);
      this.chooseTarget(game, car);
    }

    const toTarget = this.tmp.copy(this.target).sub(car.pos);
    toTarget.y = 0;
    const distance = toTarget.length();
    const desiredYaw = Math.atan2(-toTarget.z, toTarget.x);
    const diff = wrapAngle(desiredYaw - car.yaw);
    const facing = Math.cos(diff);

    let steer = clamp(-diff * 2.55 + clamp(car.vel.dot(car.right) * -0.045, -0.3, 0.3), -1, 1);
    let throttle = 1;

    if (Math.abs(diff) > 2.2) {
      throttle = -0.7;
      steer = -steer;
    } else if (Math.abs(diff) > 1.1) {
      throttle = 0.45;
    }

    // Stuck recovery near a wall.
    if (car.speed < 2.2 && Math.abs(throttle) > 0.4 && this.reverseTimer <= 0) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 0.85) {
        this.reverseTimer = 0.6;
        this.stuckTimer = 0;
      }
    } else if (this.reverseTimer <= 0) {
      this.stuckTimer = Math.max(0, this.stuckTimer - dt * 2);
    }
    if (this.reverseTimer > 0) {
      this.reverseTimer -= dt;
      throttle = -1;
      steer = clamp(-steer, -1, 1);
    }

    const ballDistance = car.pos.distanceTo(ball.pos);
    const aligned = facing > 0.78;

    // Control speed when lining up so the bot can actually touch the ball
    // instead of blasting past it.
    if (this.mode === 'approach' && distance < 9 && car.speed > 24) throttle = -0.2;
    if (this.mode === 'defend' && distance < 7 && car.speed > 18) throttle = -0.25;
    if (this.mode === 'loop' && distance < 6) throttle = 0.35;

    let boost = false;
    if (car.boost > 8 && this.boostTimer <= 0 && distance > 15 && aligned && !this.strike) {
      boost = Math.random() < this.skill.boostLove * 0.9 + 0.04;
      if (boost) this.boostTimer = 0.14;
    }
    if (ballDistance > 11 && this.mode === 'defend' && aligned && car.boost > 10) boost = true;
    if (this.reverseTimer > 0) boost = false;

    let jump = false;
    if (this.jumpCooldown <= 0 && this.strike) {
      const ballAbove = ball.pos.y - car.pos.y;
      if (car.grounded && ballAbove > 2.8 && ballAbove < 5.4 && ballDistance < 7 && Math.random() < this.skill.jumpLove) {
        jump = true;
        this.jumpCooldown = 0.75;
      }
    }

    return { throttle, steer, boost, jump };
  }
}

