382: // ---------------------------------------------------------------- physics
383: 
384: function collideCarBall(car) {
385:   const R = ball.radius;
386:   const hx = 2.58;
387:   const hy = 0.98;
388:   const hz = 1.34;
389:   const cos = Math.cos(car.yaw);
390:   const sin = Math.sin(car.yaw);
391:   const dx = ball.pos.x - car.pos.x;
392:   const dy = ball.pos.y - car.pos.y;
393:   const dz = ball.pos.z - car.pos.z;
394:   const lx = dx * cos - dz * sin;
395:   const ly = dy;
396:   const lz = dx * sin + dz * cos;
397:   // Only the front and sides of a car can move the ball. Without this, a car
398:   // that has just driven through the ball scoops it backwards with its rear.
399:   if (lx < -0.35) return false;
400:   const cx = clamp(lx, -hx, hx);
401:   const cy = clamp(ly, -hy, hy);
402:   const cz = clamp(lz, -hz, hz);
403:   const ddx = lx - cx;
404:   const ddy = ly - cy;
405:   const ddz = lz - cz;
406:   const dist = Math.hypot(ddx, ddy, ddz);
407:   if (dist >= R) return false;
408: 
409:   let nx;
410:   let ny;
411:   let nz;
412:   if (dist < 0.0001) {
413:     // Ball centre is inside the chassis: eject along the nose.
414:     nx = lx >= 0 ? 1 : -1;
415:     ny = 0.35;
416:     nz = lz >= 0 ? 0.2 : -0.2;
417:   } else {
418:     nx = ddx / dist;
419:     ny = ddy / dist;
420:     nz = ddz / dist;
421:   }
422:   const nLen = Math.hypot(nx, ny, nz) || 1;
423:   nx /= nLen;
424:   ny /= nLen;
425:   nz /= nLen;
426: 
427:   // Back to world space.
428:   const wx = nx * cos + nz * sin;
429:   const wy = ny;
430:   const wz = -nx * sin + nz * cos;
431:   const penetration = R - dist + 0.01;
432:   ball.pos.x += wx * penetration;
433:   ball.pos.y += wy * penetration;
434:   ball.pos.z += wz * penetration;
435: 
436:   let nx2 = wx;
437:   let ny2 = wy;
438:   let nz2 = wz;
439:   if (car.grounded && ny2 > 0.16) {
440:     // Keep grounded strikes playable and low; aerial hits can still pop the ball.
441:     ny2 = 0.16;
442:     const len = Math.hypot(nx2, ny2, nz2) || 1;
443:     nx2 /= len;
444:     ny2 /= len;
445:     nz2 /= len;
446:   }
447:   const normal = tmpA.set(nx2, ny2, nz2);
448:   const carSpeed = car.vel.length();
449:   const approach = Math.max(0, -tmpB.copy(ball.vel).sub(car.vel).dot(normal));
450:   const power = 9 + carSpeed * 0.95 + approach * 0.5 + (car.boosting ? 5 : 0);
451:   const lift = normal.y < 0.25 && carSpeed > 14 ? 2.2 + carSpeed * 0.075 : 0;
452:   ball.vel.multiplyScalar(0.34);
453:   ball.vel.addScaledVector(normal, power);
454:   ball.vel.addScaledVector(car.vel, 0.42);
455:   ball.vel.y += lift;
456:   if (ball.vel.length() > 86) ball.vel.setLength(86);
457:   ball.pos.y = Math.max(ball.pos.y, R);
458: 
459:   // A whisper of aim assist makes strikes feel deliberate rather than random.
460:   if (power > 18) {
461:     const goalSign = car.isBot ? -1 : 1;
462:     const aimX = goalSign * FIELD.halfLength - ball.pos.x;
463:     const aimZ = -ball.pos.z;
464:     const aimLen = Math.hypot(aimX, aimZ) || 1;
465:     const horizontal = Math.hypot(ball.vel.x, ball.vel.z);
466:     if (horizontal > 3) {
467:       const blend = car.isBot ? 0.17 : 0.07;
468:       ball.vel.x += ((aimX / aimLen) - ball.vel.x / horizontal) * horizontal * blend;
469:       ball.vel.z += ((aimZ / aimLen) - ball.vel.z / horizontal) * horizontal * blend;
470:     }
471:   }
472: 
473:   if (car.hitCooldown <= 0) {
474:     car.hitCooldown = 0.11;
475:     ball.lastHitBy = car.isBot ? 'orange' : 'blue';
476:     ball.lastHitTime = performance.now() / 1000;
477:     const playerHit = car === player;
478:     sound.hit(power / 34 + (playerHit ? 0.2 : 0.05));
479:     shake = Math.max(shake, clamp(power / 140, 0.08, 0.9));
480:     const color = playerHit ? TEAM.blue.accent : TEAM.orange.accent;
481:     effects.emit(ball.pos, {
482:       count: Math.round(6 + power * 0.55),
483:       color: 0xffffff,
484:       speed: 9 + power * 0.22,
485:       spread: 5,
486:       life: 0.42,
487:       size: 0.32,
488:       gravity: 3,
489:       direction: normal,
490:       jitter: 0.6,
491:     });
492:     effects.emit(ball.pos, {
493:       count: Math.round(4 + power * 0.3),
494:       color,
495:       speed: 7,
496:       spread: 4,
497:       life: 0.5,
498:       size: 0.24,
499:       gravity: 1,
500:       jitter: 0.5,
501:     });
502:     if (power > 34) {
503:       effects.ring(tmpC.copy(ball.pos).setY(Math.max(R, ball.pos.y - R + 0.1)), color, 5 + power * 0.08, 0.45);
504:     }
505:   }
506:   return true;
507: }
508: 
509: function collideCars() {
510:   const dx = botCar.pos.x - player.pos.x;
511:   const dz = botCar.pos.z - player.pos.z;
512:   const dy = botCar.pos.y - player.pos.y;
513:   const dist = Math.hypot(dx, dz);
514:   const minDist = 3.35;
515:   if (dist > 0.001 && dist < minDist && Math.abs(dy) < 2.6) {
516:     const nx = dx / dist;
517:     const nz = dz / dist;
518:     const overlap = minDist - dist;
519:     player.pos.x -= nx * overlap * 0.5;
520:     player.pos.z -= nz * overlap * 0.5;
521:     botCar.pos.x += nx * overlap * 0.5;
522:     botCar.pos.z += nz * overlap * 0.5;
523:     const relative = (botCar.vel.x - player.vel.x) * nx + (botCar.vel.z - player.vel.z) * nz;
524:     if (relative < 0) {
525:       const impulse = relative * 0.55;
526:       player.vel.x += nx * impulse;
527:       player.vel.z += nz * impulse;
528:       botCar.vel.x -= nx * impulse;
529:       botCar.vel.z -= nz * impulse;
530:       if (Math.abs(relative) > 8) {
531:         sound.land(Math.abs(relative) * 0.6);
532:         shake = Math.max(shake, 0.16);
533:         effects.emit(tmpA.copy(player.pos).lerp(botCar.pos, 0.5), {
534:           count: 14,
535:           color: 0xffe0a0,
536:           speed: 6,
537:           spread: 4,
538:           life: 0.35,
539:           size: 0.26,
540:           gravity: 4,
541:         });
542:       }
543:     }
544:   }
545: }
546: 
547: function checkPads() {
548:   for (const pad of arena.pads) {
549:     if (!pad.active) continue;
550:     const radius = pad.big ? 2.4 : 1.3;
551:     for (const car of [player, botCar]) {
552:       if (car.pos.y > 4) continue;
553:       const dx = car.pos.x - pad.x;
554:       const dz = car.pos.z - pad.z;
555:       if (dx * dx + dz * dz < radius * radius) {
556:         const amount = arena.collectPad(pad, car);
557:         if (amount > 0) {
558:           const color = pad.big ? 0xffc94d : 0x7fe0ff;
559:           effects.emit(tmpA.set(pad.x, 0.7, pad.z), {
560:             count: pad.big ? 30 : 12,
561:             color,
562:             speed: pad.big ? 10 : 6,
563:             spread: 3,
564:             life: 0.55,
565:             size: pad.big ? 0.38 : 0.24,
566:             direction: new THREE.Vector3(0, 1, 0),
567:             jitter: 0.4,
568:           });
569:           if (car === player) {
570:             sound.pickup(pad.big);
571:             updateHud(true);
572:           }
573:         }
574:       }
575:     }
576:   }
577: }
