579: function checkGoal() {
580:   const inMouth = Math.abs(ball.pos.z) < FIELD.goalHalfWidth - 0.3 && ball.pos.y < FIELD.goalHeight - 0.2;
581:   if (!inMouth) return;
582:   if (ball.pos.x > FIELD.halfLength + 0.35) onGoal('blue');
583:   else if (ball.pos.x < -FIELD.halfLength - 0.35) onGoal('orange');
584: }
