586: // ---------------------------------------------------------------- camera
587: 
588: function updateCamera(dt) {
589:   if (mode === 'menu') {
590:     menuAngle += dt * 0.065;
591:     camera.position.x = Math.sin(menuAngle * 0.42) * 18;
592:     camera.position.z = 81;
593:     camera.position.y = 38 + Math.sin(menuAngle * 0.8) * 1.8;
594:     camera.lookAt(-4, 3.2, 0);
595:     camera.fov = damp(camera.fov, 56, 3, dt);
596:     camera.updateProjectionMatrix();
597:     return;
598:   }
599: 
600:   if (mode === 'ended') {
601:     endAngle += dt * 0.09;
602:     camera.position.x = Math.cos(endAngle) * 68;
603:     camera.position.z = Math.sin(endAngle) * 58;
604:     camera.position.y = 30;
605:     camera.lookAt(0, 3, 0);
606:     camera.fov = damp(camera.fov, 60, 2, dt);
607:     camera.updateProjectionMatrix();
608:     applyShake(dt);
609:     return;
610:   }
611: 
612:   if (cameraMode === 'goal' && ball.pos) {
613:     camDesired.set(ball.pos.x + (ball.pos.x > 0 ? -17 : 17), 9.5, ball.pos.z + 13);
614:     camLook.copy(ball.pos).add(tmpA.set(0, 2.2, 0));
615:     camera.position.lerp(camDesired, 1 - Math.exp(-3.2 * dt));
616:     camera.lookAt(camLook);
617:     camera.fov = damp(camera.fov, 66, 3, dt);
618:     camera.updateProjectionMatrix();
619:     applyShake(dt);
620:     return;
621:   }
622: 
623:   playerForward.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
624:   const speed = player.speed;
625:   const back = 11.4 + clamp(speed / 50, 0, 1) * 1.7;
626:   camDesired.copy(player.pos).addScaledVector(playerForward, -back);
627:   camDesired.y += 4.55;
628:   camDesired.x = clamp(camDesired.x, -54, 54);
629:   camDesired.z = clamp(camDesired.z, -36, 36);
630:   camDesired.y = clamp(camDesired.y, 2.6, 30);
631: 
632:   const lookAhead = 10 + clamp(speed / 50, 0, 1) * 3.5;
633:   camLook.copy(player.pos).addScaledVector(playerForward, lookAhead);
634:   camLook.y += 2.1;
635:   camLook.addScaledVector(player.vel, 0.045);
636: 
637:   camera.position.lerp(camDesired, 1 - Math.exp(-7.5 * dt));
638:   camera.lookAt(camLook);
639:   const fovTarget = 70 + clamp(speed / 51, 0, 1) * 8 + (player.boosting ? 3.5 : 0);
640:   camera.fov = damp(camera.fov, fovTarget, 4.5, dt);
641:   camera.updateProjectionMatrix();
642:   applyShake(dt);
643: }
644: 
645: function applyShake(dt) {
646:   shake = Math.max(0, shake - dt * 2.4);
647:   if (shake <= 0.001) return;
648:   const amount = shake * 0.55;
649:   shakeOffset.set(
650:     (Math.random() - 0.5) * amount,
651:     (Math.random() - 0.5) * amount * 0.8,
652:     (Math.random() - 0.5) * amount,
653:   );
654:   camera.position.add(shakeOffset);
655: }
