657: // ---------------------------------------------------------------- updates
658: 
659: function updatePlaying(dt) {
660:   if (kickoffTimer > 0) kickoffTimer -= dt;
661: 
662:   if (!overtime) {
663:     matchTime -= dt;
664:     if (matchTime <= 0) {
665:       matchTime = 0;
666:       if (scoreBlue === scoreOrange) {
667:         overtime = true;
668:         showBanner('OVERTIME', 'NEXT GOAL WINS', '', 2.1);
669:         sound.countdown(true);
670:         arena.updateScoreboard(scoreBlue, scoreOrange, clockText(), modeText());
671:       } else {
672:         endMatch();
673:         return;
674:       }
675:     }
676:   }
677: 
678:   const controls = input.sample();
679:   if (controls.reset) resetPlayerCar();
680:   player.update(dt, controls, effects);
681:   const botControls = bot.update(dt, { ball, botCar });
682:   botCar.update(dt, botControls, effects);
683: 
684:   ball.update(dt, effects, true);
685: 
686:   collideCarBall(player);
687:   collideCarBall(botCar);
688:   collideCars();
689:   checkPads();
690: 
691:   if (mode !== 'playing') return;
692:   checkGoal();
693:   if (mode !== 'playing') return;
694: 
695:   if (hintTimer > 0) {
696:     hintTimer -= dt;
697:     if (hintTimer <= 0) ui.controlHint.style.opacity = '0';
698:   }
699: 
700:   hudAccumulator += dt;
701:   if (hudAccumulator > 0.06) {
702:     hudAccumulator = 0;
703:     updateHud();
704:   }
705:   updateCamera(dt);
706:   sound.updateEngine(player.speed, controls.throttle, player.boosting, true);
707: }
708: 
709: function updateGoalState(dt) {
710:   goalTimer -= dt;
711:   const idle = { throttle: 0, steer: 0, boost: false, jump: false };
712:   player.update(dt, idle, effects);
713:   botCar.update(dt, idle, effects);
714:   ball.update(dt, effects, false);
715:   updateCamera(dt);
716:   sound.updateEngine(player.speed, 0, false, false);
717:   if (goalTimer <= 0) {
718:     const matchOver = scoreBlue >= 3 || scoreOrange >= 3 || overtime;
719:     if (matchOver) {
720:       endMatch();
721:     } else {
722:       cameraMode = 'chase';
723:       resetKickoff(false);
724:     }
725:   }
726: }
727: 
728: function updateEnded(dt) {
729:   const idle = { throttle: 0, steer: 0, boost: false, jump: false };
730:   player.update(dt, idle, effects);
731:   botCar.update(dt, idle, effects);
732:   ball.update(dt, effects, false);
733:   updateCamera(dt);
734:   sound.updateEngine(player.speed, 0, false, false);
735: }
736: 
737: // ---------------------------------------------------------------- loop
738: 
739: let lastTime = performance.now();
740: 
741: function tick(now) {
742:   requestAnimationFrame(tick);
743:   const dt = Math.min(0.034, Math.max(0.0001, (now - lastTime) / 1000));
744:   lastTime = now;
745:   frameCount += 1;
746: 
747:   arena.update(dt);
748: 
749:   if (paused) {
750:     sound.updateEngine(0, 0, false, false);
751:     composer.render();
752:     return;
753:   }
754: 
755:   if (mode === 'menu') {
756:     menuAngle += 0;
757:     ball.update(dt, effects, false);
758:     player.update(dt, { throttle: 0, steer: 0, boost: false, jump: false }, effects);
759:     botCar.update(dt, { throttle: 0, steer: 0, boost: false, jump: false }, effects);
760:     effects.update(dt);
761:     updateCamera(dt);
762:     sound.updateEngine(0, 0, false, false);
763:   } else if (mode === 'playing') {
764:     updatePlaying(dt);
765:     effects.update(dt);
766:   } else if (mode === 'goal') {
767:     updateGoalState(dt);
768:     effects.update(dt);
769:   } else if (mode === 'ended') {
770:     updateEnded(dt);
771:     effects.update(dt);
772:   }
773: 
774:   composer.render();
775: }
