154:     const t0 = ctx.currentTime + delay;
155:     const src = ctx.createBufferSource();
156:     src.buffer = this.noiseBuffer;
157:     const filter = ctx.createBiquadFilter();
158:     filter.type = type;
159:     filter.frequency.value = freq;
160:     filter.Q.value = q;
161:     const g = ctx.createGain();
162:     g.gain.setValueAtTime(gain, t0);
163:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
164:     src.connect(filter);
165:     filter.connect(g);
166:     g.connect(this.master);
167:     src.start(t0, Math.random() * 1.5);
168:     src.stop(t0 + dur + 0.05);
169:   }
170: 
171:   ui() {
172:     this.tone({ freq: 520, to: 740, dur: 0.09, type: 'triangle', gain: 0.12 });
173:   }
174: 
175:   countdown(final = false) {
176:     this.tone({ freq: final ? 620 : 380, to: final ? 820 : 380, dur: final ? 0.28 : 0.12, type: 'square', gain: 0.09 });
177:   }
178: 
179:   jump() {
180:     this.tone({ freq: 240, to: 520, dur: 0.15, type: 'triangle', gain: 0.13 });
181:     this.noise({ dur: 0.12, gain: 0.08, freq: 1400 });
182:   }
183: 
184:   doubleJump() {
