186:   }
187: 
188:   land(impact = 8) {
189:     const p = Math.min(1, impact / 18);
190:     this.tone({ freq: 100, to: 45, dur: 0.18, type: 'sine', gain: 0.12 + p * 0.12 });
191:     this.noise({ dur: 0.12, gain: 0.05 + p * 0.1, freq: 300, type: 'lowpass' });
192:   }
193: 
194:   hit(power = 1) {
195:     const p = Math.min(1.5, power);
196:     this.tone({ freq: 150 + p * 40, to: 48, dur: 0.16, type: 'sine', gain: 0.18 + p * 0.14 });
197:     this.tone({ freq: 320 + p * 90, to: 160, dur: 0.1, type: 'triangle', gain: 0.05 + p * 0.04 });
198:     this.noise({ dur: 0.16, gain: 0.12 + p * 0.1, freq: 900 + p * 400 });
199:   }
