```
const controls = input.sample();
if (controls.reset) {
  if (onFoot) { /* teleport character to car? */ } else resetPlayerCar();
}
if (controls.interact) {
  if (onFoot) enterCar(); else exitCar();
}
footKickCooldown = Math.max(0, footKickCooldown - dt);
applyFootLook(controls.lookX, controls.lookY, dt);
if (onFoot) {
  character.update(dt, controls, footYaw, effects);
  collideCharacterBall();
  collideCharacterCar();
  player.update(dt, {idle}, effects);
} else {
  player.update(dt, controls, effects);
}
bot...
...
collideCarBall(player); collideCarBall(botCar);
if (!onFoot) { /* character hidden */ } else collideCharacterBall again? We already did before car update; ball updates before? Sequence:
```
